/* ★ 0921z：项目存储根来源（相对 root_path 兜底解析用；设置页改了存储目录也热读） */
setProjectStorageRootProvider(() => String((globalSettings as any).storagePath || defaultStorageRoot()))
// 0924 二期批6b-2：记忆蒸馏的 LLM 注入（依赖倒置，避免 memoryBridge↔server 循环引用）
/* ★1012t：后台模型的 override 形态（{provider, model_id}）。
   ★1013：未配置 / 所指供应商不可用 → null —— **不再回落全局聊天模型**（调用方必须明确失败 + 提醒）。 */
function backgroundLlmCfg(): { provider: string; model_id: string; effort?: string | null } | null {
  const c = backgroundLlmConfig()
  // ★1013：effort 一起带上 —— 提炼这类非对话调用也要按后台模型自己的强度跑
  return c.configured ? { provider: c.providerId, model_id: c.model, effort: c.effort } : null
}
/* ★1012t：后台模型调用失败 → 广播一条「系统通知」，前端 pushSystem 落进侧边栏铃铛面板。
   用户需求原话："提炼的时候触发了，全局模型要是没费用了或者报错，要发一条系统通知"。
   防刷屏：同类错误 60 秒内只发一条（提炼/蒸馏可能重试或批量触发，不然面板会被刷爆）。 */
const _bgFailLastAt = new Map<string, number>()
function notifyBackgroundModelFailure(what: string, err: unknown): void {
  try {
    const detail = String((err as any)?.message || err || '未知错误').slice(0, 220)
    const cfg = backgroundLlmConfig()
    const key = `${what}|${detail.slice(0, 60)}`
    const now = Date.now()
    if (now - (_bgFailLastAt.get(key) || 0) < 60_000) return
    _bgFailLastAt.set(key, now)
    /* ★1013：未配置后台模型时，这条通知本身就是"去设置里选一个"的行动指引（用户："留空就弹提醒让用户自己去选"） */
    const _who = cfg.configured ? `${cfg.providerName || cfg.providerId} / ${cfg.model}` : '未配置'
    broadcastHost({
      type: 'host/system-notice',
      level: 'error',
      category: 'error',
      title: cfg.configured ? `${what}失败（后台模型）` : `未配置「后台模型」——${what}干不了活`,
      message: `${_who}：${detail}`,
    })
    console.warn(`[background-model] ${what} 失败 → 已发系统通知：`, detail)
  } catch { /* 通知本身失败不影响主流程 */ }
}
/* ★1012t：记忆蒸馏/提炼改走**后台模型**（已定案："这个全局模型我本想的就是作为一个对话之外的工作模型，
   能不能把他们分开"，命名「后台模型」）。opts.override 若被调用方显式传入（个别场景自带指定模型）仍优先尊重。
   失败 → 发系统通知（提炼是最典型的"后台模型挂了"场景，见上）。 */
setDistillLlm(async (prompt, system, opts) => {
  const _ov = (opts as any)?.override || backgroundLlmCfg()
  /* ★1013（已定案）：后台模型没配 ⇒ **不做任何回落**（拿聊天模型顶上 = 偷用户的钱），
     直接失败并弹通知，把"去 设置 → 通用 → 模型 → 后台模型 选一个"摆到用户面前。 */
  if (!_ov) {
    const why = backgroundLlmConfig().reason || '未配置「后台模型」'
    notifyBackgroundModelFailure('记忆/知识提炼', why)
    throw new Error(why)
  }
  try {
    return await llmOnceDirect(prompt, system, { ...(opts as any), override: _ov })
  } catch (e) {
    notifyBackgroundModelFailure('记忆/知识提炼', e)
    throw e
  }
})

/* ★ 0921z：存量 root_path 自愈（相对路径 → 绝对路径）。
 *  必须在 loadSessions() **之前**——此时 projects.json / sessions/*.json 尚未进内存，
 *  直接改盘不会被内存缓存回写覆盖。幂等；落盘前整份备份（projects.json.bak-rootpath-*）。 */
/* ★1032-TM（P109）：**启动分段计时** —— 实测"刚打开就卡 9 秒"（`[eventloop] 主线程被堵 9218ms`）。
   启动这一段全是同步 FS：扫存量会话（915 个）→ 加载会话 → 扫僵尸 run。
   没有打点就只能猜是哪一步，所以这里留下每步的耗时（启动日志里一眼能看到，常驻不碍事）。 */
const _bootAt = (label: string, t0: number) => console.log(`[boot-t] ${label} ${Date.now() - t0}ms`)
/* ★1032-TM（P109）：**迁移做过一次就不再扫盘**。
   它每次启动都遍历 915 个会话文件检查 root_path（实测 9052ms），而结果永远是"全部为绝对路径"。
   迁移函数本身是幂等的 —— 但幂等不等于"该每次都跑"：完成状态是**事实**，落一个标记文件，
   只有 storageRoot 变了（用户改存储路径）才重扫。 */
const ROOT_PATH_MARK = path.join(DATA_ROOT, '.rootpath-migrated.json')
const _storageRootNow = String((globalSettings as any).storagePath || defaultStorageRoot())
const _rootPathDone = (() => {
  try {
    const m = JSON.parse(fs.readFileSync(ROOT_PATH_MARK, 'utf8') || '{}')
    return !!m && m.version === 1 && String(m.storageRoot || '') === _storageRootNow
  } catch { return false }
})()
if (_rootPathDone) {
  console.log('[paths] 存量 root_path 检查：已迁移过（标记命中，跳过扫盘）')
} else try {
  const _tMig = Date.now()
  const mig = migrateRootPathsOnDisk({
    dataRoot: DATA_ROOT,
    storageRoot: _storageRootNow,
  })
  _bootAt('migrateRootPaths', _tMig)
  try {
    fs.writeFileSync(ROOT_PATH_MARK, JSON.stringify({ version: 1, storageRoot: _storageRootNow, at: Date.now() }), 'utf8')
  } catch (e: any) {
    console.error('[paths] 迁移标记写入失败（下次启动会重扫，不影响正确性）：', e?.message || e)
  }
  const np = mig.projects.changed.length
  const ns = mig.sessions.changed.length
  if (np || ns) {
    console.log(`[paths] 存量 root_path 迁移：项目 ${np} 个、会话 ${ns} 条`)
    for (const c of mig.projects.changed) console.log(`[paths]   项目「${c.name}」${c.from} → ${c.to}${c.resolved ? '' : '  ⚠ 未找到真实目录，按存储根兜底'}`)
    if (mig.backup) console.log(`[paths]   备份：${mig.backup}`)
    if (mig.sessionBackup) console.log(`[paths]   会话备份：${mig.sessionBackup}`)
  } else {
    console.log(`[paths] 存量 root_path 检查完成：${mig.projects.scanned} 个项目 / ${mig.sessions.scanned} 个会话，全部为绝对路径`)
  }
} catch (e) {
  console.error('[paths] 存量 root_path 迁移失败（不影响启动）：', e)
}

{
  const _tLoad = Date.now()
  loadSessions()
  _bootAt('loadSessions', _tLoad)
}
/* ★1032（P12）：进程重启后，落盘里所有 running 都是僵尸 —— 先修正，再对外服务。 */
{
  const _tSweep = Date.now()
  sweepZombieRuns()
  _bootAt('sweepZombieRuns', _tSweep)
}
/* ★f3（已批）：**同一条口径的第二处** —— memberStates 里停在 running 的成员状态。
   为什么不并进 sweepZombieRuns：那是 run 账本（`subRuns`），这是成员徽标/面板状态（`memberStates`），
   两份数据、两个落盘字段；但**判据与语义完全相同**（重启 ⇒ in-flight 终止 ⇒ 标 interrupted），
   所以紧挨着放、日志口径对齐，方便一起查。 */
{
  const _tSweepMs = Date.now()
  sweepZombieMemberStates()
  _bootAt('sweepZombieMemberStates', _tSweepMs)
}
/* ★d2x：原 D-P0 的启动扫场（sweepDisarmGoals）已删 —— `goal` 不在 hydrate 白名单里，
   内存中 session.goal 恒 undefined ⇒ 扫场永远零改动，只是每次启动白扫一遍全部会话。 */
// ★1033：卡顿取证探针启动（只观测，正常路径零输出；见 handleRpc 上方的说明块）
startEventLoopProbe()
// 0911 #16：启动即完成一次落盘——把冷启动成本（旧单文件迁移成 sessions/ 目录、base64 剥离写 assets）
// 提前到启动阶段；此后每次 schedulePersist 都是热态（strip ~140ms + stringify ~80ms）。
try { persistSessionsSync() } catch { /* ignore */ }

// Agent 预设：启动 seed（内置预设文件夹不存在时写入，已有不覆盖）
initAgentPresets()

// MCP 运行时：按配置目录后台连接（失败不影响主服务）
// 先注册内置虚拟 server（让 mcpHubConnect 的 virtual 守卫在其后的磁盘扫描里生效），再扫描磁盘真 MCP
registerBuiltinVirtualServers()
/* ★1117：`applyBrowserSettingsToEngine(loadBrowserSettings())` 已删除 ——
   那套设置（投屏 fps/画质、反爬、屏蔽媒体、GPU、代理）在壳模式下不生效，随死配置一起移除。
   引擎内部仍用模块级默认值（`render` / `cast` 常量），local 兜底路径行为不变。 */
/* ★fitmcp（审计-6 P1）：MCP 断线 → 推帧通知前端（否则用户完全不知道工具已经哑火）。
   分层：mcpRuntime 只报事件，推帧在这里做（模块层不该认识 WS）。
   ① `host/system-notice` → 侧边栏铃铛面板，用户能看见"哪个服务断了、原因、会自动重连一次"；
   ② 插件页/工具页的连接态走既有 RPC 拉取（mcp.list / preset.tools），markDisconnected 已把
      status 置 disconnected、tools 清空 ⇒ 打开即看到，工具不再注入。 */
setMcpStatusListener((ev) => {
  if (ev.status !== 'disconnected') return
  try {
    broadcastHost({
      type: 'host/system-notice',
      title: `MCP 服务已断开：${ev.name}`,
      message: `${ev.reason || '连接已断开'}。已停止向 agent 注入该服务的工具；下次调用它的工具时会自动重连一次，若仍失败请在「插件 → MCP 工具」里手动重连。`,
      level: 'error',
    } as any)
  } catch (e) { swallowed('MCP 断线通知推帧失败（前端不会收到断线提示）', e) }
})
void mcpHubInit()

// 会话执行日志：清理 7 天前旧文件
cleanupOldLogs()
// 团队存储：目录为空时写入示例团队
initTeams()

// 成员单聊回写守卫（0904）：runMemberChat 结束落库前查会话是否仍存活（删除后迟到结果不回写）

// 0911 反馈③：文件写锁的 run 存活查询（残留锁兜底——owner run 已失活时新持有者可直接抢锁）
setFileLockRunLiveness(isRunActive)

// 0911：成员单次运行上限热读（设置·通用「成员单次运行上限」）。档位 30/60/120/240 分钟、0=不设限；
// 映射：activeMs=连续工作硬上限（权限等待挂起不计入），wallMs=绝对墙钟（含挂起）= 2×activeMs。
// 不设限时仅保留无活动看门狗（teamRuntime 内部常量）——防挂死兜底永远在。
/* ★p1d：**把成员子流的 LLM 在途事实接到看门狗上**（默认路径 runMemberTurn 必需）。
   默认派发的流在 createStreamFn 内部建（opts.sub=true），teamRuntime 拿不到句柄 ⇒ 只能在 server 这边回调。
   打点判据 = "调 streamFn → result() settle"（天然成对，成功/失败/中断都覆盖）；
   不用 turn_start/turn_end / message_* 的原因见 setMemberStreamOpHook 的注释。 */
installMemberStreamOpHook((h) => setMemberStreamOpHook(h))
setMemberRunLimitProvider(() => {
  const m = Number((globalSettings as any).memberRunLimitMinutes)
  const raw = Number.isFinite(m) ? m : 30
  if (raw === 0) return { activeMs: Number.POSITIVE_INFINITY, wallMs: Number.POSITIVE_INFINITY }
  const activeMs = Math.max(15, Math.min(480, raw)) * 60_000
  return { activeMs, wallMs: activeMs * 2 }
})

// 0911 三批：成员巡检官——规则预筛常驻（零成本）；复审走 inspectorReviewDirect 轻量直调。
// 开关走设置·通用（memberInspector，默认开），热读无需重启；复审失败静默（不影响成员运行）。
setMemberInspectorProvider(() => (globalSettings as any).memberInspector !== false)
setInspectorReviewer(inspectorReviewDirect)
/* ★1005（已定案"分身还在跑 ⇒ 会话就是进行中"）：最后一个成员/分身 run 收尾 →
   把会话置 idle 并广播（**这里才是权威的收轮点**，前端零启发式）。 */
setSubAgentsIdleHook((sid) => {
  try {
    const s = sessions.get(String(sid || ''))
    if (!s || s.status !== 'running') return   // 已被 abort/cancel 置 idle：不重复
    /* ★1032（P15 **根因修正**）：原来这里用 `agents.get(sid)` 判断"是不是刚拉起了新一轮"——
       但 **agent 实例是缓存，收轮后不会删除**（只有 cancel/delete 才删）⇒ 这个条件**恒为真**
       ⇒ 钩子永远提前 return ⇒ ① 会话永远不置 idle ② 我加的 `flushNextQueued` 永远不执行
       （实测：插话进队列后 3 分半没人发）。
       正确判据是"**这一刻是否真的在跑**"（`sessionAgentBusy`：activeRun / isStreaming）。 */
    if (sessionAgentBusy(String(sid || ''))) return
    /* ★1034（**这里才是真正的收轮点**）：最后一个分身/成员 run 刚收尾 ⇒ 用还活着的累加器
       推最后一帧（带上 run 的 done/timeout/interrupted 终态），**然后**再摘累加器。
       原来只置 idle 不推帧：`agent_end` 那边早把累加器删了，终态帧根本发不出去 ⇒
       前端停在 running（实测"点停止后气泡一路涨到 1分41s，其实后端 24s 就结束了"）。 */
    try {
      const acc = turnAccumulators.get(String(sid))
      if (acc) pushTurnSnapshot(String(sid), acc, true)
    } catch { /* 推帧失败不拦置 idle */ }
    turnAccumulators.delete(String(sid))
    /* ★p0b-B1：走统一收尾出口（钩子在 runMap.delete 之后触发 ⇒ 在跑数已为 0 ⇒ status 仍是 idle） */
    endTurnState(String(sid), s)
    s.updatedAt = Date.now()
    schedulePersist()
    broadcastMux(String(sid), statusFrame(String(sid), { mainRunning: false }))
    broadcastHost({ type: 'host/session-status', sessionId: String(sid), running: false })
    sessionLog(String(sid), 'info', 'lifecycle', '所有分身/成员 run 已收尾，会话置 idle')
    /* ★1032（P15 **最后一个缺口**）：**空闲这一刻续发队列** ——
       分身跑着时用户说的话进了 `queuedMessages`（被 `status !== 'idle'` 闸门挡住是对的），
       但原来这里只置 idle、**不 flush** ⇒ 队列永远躺着（实测：插话排队后 3 分钟没人发）。
       `flushNextQueued` 自己带闸门（empty/paused/agent-busy/inflight/interaction/error），这里直接调安全。 */
    try { flushNextQueued(String(sid)) } catch (e) { console.warn('[队列] 分身收尾后续发失败:', e) }
  } catch (e) { console.warn('[subagent] 会话置 idle 失败:', e) }
})

// 1114 砍掉「会话数据启动滚动备份」（原 backupOneDirOnStartup / backupSessionsOnStartup）：
//   ① 判空只看 `endsWith('.json')`，而 sessions/ 早已是「每会话一个目录」⇒ 顶层全是目录名 ⇒ 恒 false
//      ⇒ 从 11-10 起就静默失效，再没生成过任何副本（注释写着"失败不许静默"，但这个 return 恰好是静默的）；
//   ② 全项目只有**写** backups 的代码，没有任何"从 backups 恢复"的入口 ⇒ 出事后只能人工翻目录；
//   ③ 副本与源数据同盘同目录树，防不住磁盘坏 / 误删 data / 勒索 —— 假安全比没有更糟。
// 备份职责交给「设置 → 通用 → 数据备份」整包导出：DATA_PARTS 含 sessions + session-assets，能真的导回来。

/**
 * 群聊「插嘴」（0912 二十四批）—— 没人 @ 它，它也可能主动搭一句。
 *
 * 触发条件（**全部满足**才插）：
 *   ① 该机器人的「群聊插嘴」开关开着（默认关）；
 *   ② 消息不是机器人自己发的（qqBot 层已过滤其他机器人）、不是空/纯占位；
 *   ③ 内容门槛：interjectScope='question'（默认）时，消息得**像提问**
 *      （问号 / 吗呢吧 / 怎么为什么什么哪里谁求帮…）；'any' 则任何消息都可能接；
 *      **'keyword'（0914 新增：仅插嘴词触发）—— 没命中插嘴词一律不接，全天候只有喊词才出声**；
 *      另外任何 scope 下命中插嘴词都直接越过门槛（question 模式亦然）；
 *   ④ 节流：距上次机器人发言 ≥ 8 分钟，且近 1 小时插嘴次数 < 上限（默认 3）。
 *
 * 插嘴走**正常回复链路**（resolveChannelSession + runPromptCore），用该群会话的模型/人格；
 * 结果通过 QQ 群消息发出（窗口内被动回复，不占主动额度）。
 */
async function maybeInterjectInGroup(botId: string, ev: any, speakerLabel: string): Promise<void> {
  const groupId = String(ev?.target || '')
  if (!groupId) return
  // ① 开关
  const bot = getChannel('qq')?.bots?.find(b => b.id === botId)
  if (!bot?.interject) return
  // ② 内容门槛
  const text = String(ev?.content || '').trim()
  if (!text || /^\[(图片|文件|视频|语音)[^\]]*\]$/.test(text)) return
  const scope = bot.interjectScope === 'any' ? 'any' : bot.interjectScope === 'keyword' ? 'keyword' : 'question'
  /** 0912 反馈：插嘴词 —— 命中即**越过内容门槛**（群里喊它 / 喊关键词时，不算提问也接一句） */
  const kws = Array.isArray(bot.interjectKeywords)
    ? bot.interjectKeywords.map((k: any) => String(k || '').trim()).filter(Boolean)
    : []
  const hitWord = kws.find((k: string) => text.includes(k))
  // 0913 防串台：这条消息在喊「别的机器人」（命中同群其它 bot 的插嘴词/名字）而没喊我 → 不接。
  // 背景：两个 bot 都开 scope=any 时，「牢大说话」会被 Nis 当普通闲聊接走（用户报的串台）。
  const otherWakeWords = ((getChannel('qq') as any)?.bots || [])
    .filter((b: any) => b && b.id !== botId)
    .flatMap((b: any) => [b.nickname, ...(Array.isArray(b.interjectKeywords) ? b.interjectKeywords : [])])
    .map((s: any) => String(s || '').trim())
    .filter(Boolean)
  const otherHit = (otherWakeWords as string[]).find((k: string) => k && text.includes(k))
  /** 0914 修订：只在**对方被直接召唤**时让位（"顺手提到"仍可搭腔——需求过"提到它搭腔挺有意思"）；
   *  消息里有我的名字或命中我的词时一定接（如"牢大说话，nis 也来"）。 */
  const myName = String((bot as any)?.nickname || '').trim()
  const myNameHit = !!myName && text.includes(myName)
  const summonOther = !!otherHit && /(说话|说两?句|出来|在吗|在不在|上线|冒泡|吱声|回(个)?话|来一下|过来|叫|喊)|呢[？?]?$/.test(text)
  if (summonOther && !hitWord && !myNameHit) {
    console.log(`[interject] 群 ${groupId.slice(0, 8)} 跳过：消息在喊别的机器人（命中「${otherHit}」）`)
    return
  }
  // 0914：'keyword'（仅插嘴词触发）—— 没命中插嘴词一律不接（其他 scope 命中词照样直接过，上面的 !hitWord 判断不变）
  if (scope === 'keyword' && !hitWord) return
  if (!hitWord && scope === 'question' && !looksLikeQuestion(text)) return
  // ③ 节流（冷却时间可配：0 = 不设冷却，仍受每小时上限约束）
  const perHour = typeof bot.interjectPerHour === 'number' ? bot.interjectPerHour : 3
  const cooldownSec = typeof bot.interjectCooldownSec === 'number' ? Math.max(0, bot.interjectCooldownSec) : 480
  const gate = canInterject('qq', groupId, cooldownSec * 1000, perHour)
  if (!gate.ok) {
    console.log(`[interject] 群 ${groupId.slice(0, 8)} 跳过：${gate.reason}`)
    return
  }
  // ④ 执行：拿到该群会话 → 跑一轮 → 把结果发回群里
  const peerLabel = (() => {
    try { return labelFor('qq', botId, groupId, 'group') || `QQ 群 · ${groupId.slice(0, 6)}` } catch { return `QQ 群 · ${groupId.slice(0, 6)}` }
  })()
  const sid = resolveChannelSession('qq', botId, groupId, peerLabel, { kind: 'group' })
  if (!sid) return
  /**
   * 插嘴提示词：明确告诉它在"主动搭话"（不是被问），并要求简短 ——
   * 群里主动说话太长会显得很吵。
   * 0912 反馈：原版结尾「如果这句其实没什么好接的，只回一个（跳过）」太容易让模型偷懒跳过
   * （实测「不 @ 它问一句它也不出来」）→ 改成"能接就接"，只有完全接不上才跳过；
   * 命中插嘴词时更明确要求必须开口。
   */
  /** 0914 防身份互串：插嘴补一句"身份锚"——只代表自己，不冒充/不代群里其他人发言。
   *  由来：实测两个 bot 同群时，A 回了"喊 B 的话"且口吻疑似 B（串台观感）。 */
  const selfNick = String((bot as any)?.nickname || '').trim()
  const identNote = selfNick
    ? `\n（身份提醒：你在本群的昵称是「${selfNick}」，你只代表你自己说话；不要冒充、也不要替群里的其他发言者说话。）`
    : ''
  const hint = (hitWord
    ? `【群聊插嘴·有人点名】群里 ${speakerLabel} 说：「${text}」（提到了「${hitWord}」）\n` +
      `你主动接一句，很简短（一两句话以内），像群里朋友随口搭腔的自然口吻。\n` +
      `这次是有人提到你，务必开口回应，不要回「（跳过）」。`
    : `【群聊插嘴】群里 ${speakerLabel} 刚说：「${text}」\n` +
      `你（这个机器人）主动接一句，很简短（一两句话以内），像群里朋友随口搭腔的自然口吻。\n` +
      `只要能自然接上一句就接（附和、调侃、给个看法都行），只有完全接不上时才回「（跳过）」。`) + identNote
  console.log(`[interject] 群 ${groupId.slice(0, 8)} 生效${hitWord ? `（命中插嘴词「${hitWord}」）` : ''}：${speakerLabel}「${text.slice(0, 30)}」`)
  /* ★0927 P0-1：插嘴随后要读本轮回复发回群里 → 忙时必须等（blocking 语义不变），不能排队后立刻读。
     等不到（超 10 分钟）自动转队列，消息不丢。 */
  /* ★1014c：插嘴也要能看见"群里刚发的图" —— 只接 @ 那条路的话，它自己插嘴时照样是瞎子（产品要求）。
     ⚠️ 模型不支持看图时**不塞图**：塞了 runPromptCore 会直接抛错，整条插嘴就哑火（宁可这次没图）。 */
  const ijImages = await claimGroupMedia('qq', botId, groupId)
  const ijSession = sessions.get(sid)
  const ijGate = ijSession ? channelVisionGate(ijSession) : { blocked: false, model: '' }
  const ijAttachments = ijImages.length && !ijGate.blocked
    ? ijImages.map(i => ({ name: path.basename(i.path), dataUrl: i.dataUrl }))
    : []
  if (ijImages.length && ijGate.blocked) {
    console.log(`[interject] 群 ${groupId.slice(0, 8)}：有 ${ijImages.length} 张图待认领，但模型「${ijGate.model}」不支持看图 → 本次不带图`)
  }
  /* ★1020（身份统一 · 通道侧收尾）：群插嘴也是"用户发话" —— 给确定性 id 并交给落盘（同单聊口径）
     ★1124y（**实测 357 条**：插嘴的整段指令被当成用户消息落盘 ⇒ 会话里长出一堆
       「【群聊插嘴】群里 X 刚说…你主动接一句…只有完全接不上时才回（跳过）」的用户气泡）：
       · 落盘正文只留**那句引述**（`【群聊插嘴】群里 X：「…」`）—— 用户看得懂"谁说了什么"；
       · 完整指令走 `modelContext`（只给模型看）；
       · `__inject` + INJECT_MARKERS 的 `【群聊插嘴` ⇒ 这一轮是**注入段**（前端按通知显示，不算用户轮）。 */
  const ijRpcId = `ch:group:${Date.now().toString(36)}:${Math.random().toString(36).slice(2, 8)}`
  pushPendingUserRpcId(sid, ijRpcId)
  await runPromptCore(sid, {
    message: `【群聊插嘴${hitWord ? '·有人点名' : ''}】群里 ${speakerLabel}：「${text}」`,
    modelContext: hint,
    __inject: { merge: false, at: Date.now(), kind: 'group_interject' },
    rpcId: ijRpcId,
    __busyPolicy: 'wait',
    ...(ijAttachments.length ? { attachments: ijAttachments } : {}),
  })
  // 出站 @ 同群聊口径：剥掉误留的 `<@id>` 字面量（插嘴不走 deliverToChannel，这里单独过一道；不自动补 @）
  const out = toMentionText(extractFinalAssistantText(sid).trim(), undefined)
  if (!out || /^（跳过）$|^\(跳过\)$/.test(out)) {
    console.log(`[interject] 群 ${groupId.slice(0, 8)} AI 判定无需接话，跳过`)
    return
  }
  // 被动回复（用这条消息的 id，窗口内不占主动额度）
  await sendQqMessage(botId, { kind: 'group', target: groupId, messageId: String(ev.messageId || '') }, out)
    .then(() => { markInterject('qq', groupId) })
    .catch(async (e: any) => {
      console.warn(`[interject] 群发失败，尝试主动消息: ${String(e?.message || e).slice(0, 120)}`)
      try {
        await sendQqMessage(botId, { kind: 'group', target: groupId, messageId: '' }, out)
        markInterject('qq', groupId)
      } catch (e2: any) {
        console.warn(`[interject] 群发彻底失败: ${String(e2?.message || e2).slice(0, 120)}`)
      }
    })
}

/** 消息像不像提问（插嘴默认只接这类；纯灌水不接） */
function looksLikeQuestion(text: string): boolean {
  const s = String(text || '').trim()
  if (!s) return false
  if (/[?？]/.test(s)) return true
  if (/(吗|呢|吧)[？?]?$/.test(s)) return true
  return /(怎么|怎样|如何|为什么|为啥|什么|哪个|哪种|哪里|哪儿|谁|求|帮个忙|帮忙|有没有|能不能|可不可以|是不是|对不对|教我|解释一下)/.test(s)
}

// 0910 缓存优化：启动即预热技能缓存——agent 创建路径的 skillsSnapshotSync() 依赖它同步拼 system；
// 冷缓存=首请求没有技能清单、异步补写=前缀断一次。预热后再 listen，首建 agent 必命中热缓存。
getSkills().catch(() => { /* 目录缺失/加载失败=无技能，不拦启动 */ }).finally(() => {
  /* 0920：监听地址从 127.0.0.1 改成 **0.0.0.0** —— 「接入 → 远程访问」要能让手机/另一台电脑
  /* 0920：监听地址从 127.0.0.1 改成 **0.0.0.0** —— 「接入 → 远程访问」要能让手机/另一台电脑
     用 http://<本机局域网IP>:<port>/ 打开本界面（打包版窗口仍走 127.0.0.1，不受影响）。
     ⚠️ 没有这道"总闸"就等于整台机器在内网裸奔，所以 createServer 里同步加了守卫：
     **非本机来源 + 远程访问开关未打开 → 直接 403**（开关在「接入 → 远程访问」，落 channels.json）。 */
  /* ★1035 阶段 B-1：挂 /api/ws
     开关有两种，任一成立即挂载：
       ① 环境变量 NIS_WS=1
       ② 文件 <数据根>/.ws-on 存在（★实测：PowerShell 的 Start-Process 起子进程时，
          `$env:` 里设的东西传不过去（子进程读到 undefined），所以文件开关才是可靠的那条；
          这也与项目既有惯例一致：.leak-gate / .sse-dump.off / .prune-aggressive 都是文件开关）
     两个都没有 = 路由不存在 = 与接线前完全一致（零行为变化，回滚只需删文件）。
     ─────────────────────────────────────────────────────────────────────────
     门禁的真源**只有一处**：originAllowed()。它在本文件已经含了四道判定
     （本机+本机Host → Origin；否则 远程开关 + 令牌 + Origin），HTTP 请求在 createServer 首行也是调它。
     ⇒ upgrade 阶段直接复用它，**不复制任何一条判定**（复制 = 两条实现必然漂移 = 安全回退）。
     下面额外算"精确原因"**只用于留痕与响应文案**，不参与决策 —— 决策永远是 originAllowed。 */
  /* ★1114【发布级阻断修复】——默认**开启**，只在显式 NIS_WS=0 时关闭。
     病根：SSE 两条流（`/api/events.mux` / `.host`）已删除，前端**只走 /api/ws**（见 21015 行）；
     而这里原来要求「NIS_WS=1 或 <数据根>/.ws-on 存在」才挂载。
     全新安装的数据目录里当然没有 `.ws-on` ⇒ WS 路由不存在 ⇒ 前端 `bootConnected` 永远等不到
     `niusdream-ws-connected` ⇒ 开屏 15s 超时进主界面、且之后**不再恢复**，界面恒停「未启用供应商」。
     实证：dev 的 `backend/data/.ws-on` 在 → 一切正常；安装版 `data/.ws-on` 不在 → 必挂。
     口径：WS 已经是**唯一**传输通道，不再是"可选特性" ⇒ 默认开、留一个显式关闭口用于排查。 */
  const wsFlagFile = path.join(DATA_ROOT, '.ws-on')
  const wsEnabled = process.env.NIS_WS !== '0'
  if (wsEnabled) {
    /* ★1035 阶段0 探针开关：默认关（开着要对整帧再 stringify 一次）。
       要量帧体积就建 `<数据根>/.ws-probe`，或设 NIS_PROBE=1。 */
    setProbeEnabled(process.env.NIS_PROBE === '1' || fs.existsSync(path.join(DATA_ROOT, '.ws-probe')))
    wsHub = new WsHub({
      /* 服务端身份与水位：hub 自己不知道 logEpoch，必须由这里注入（不给就省略，绝不填假值） */
      serverInfo: {
        logEpoch: LOG_EPOCH,
        /* 与 SSE 的订阅 ack 同口径（server.ts:15739）：nextSeq - 1 = 日志里最后一条的 seq，空日志回 -1 */
        watermark: (sid: string) => eventLogOf(sid).nextSeq - 1,
      },
    })
    wsAttached = attachWs({
      server,
      hub: wsHub,
      gate: (req) => {
        if (originAllowed(req)) return { ok: true }
        let status = 403
        let message = 'origin 不被信任'
        if (!isLocalRequest(req) && !remoteAccessEnabled()) {
          message = '远程访问开关未开启'
        } else if (!isLocalRequest(req) || !hostIsLoopback(req)) {
          const tok = currentAccessToken()
          if (!tok) message = '未设置访问令牌（远程访问必须带令牌）'
          else if (requestToken(req) !== tok) {
            status = 401
            message = '令牌缺失或不匹配'
          }
        }
        return { ok: false, status, message }
      },
    })
    wsHub.startHeartbeat()
    /* ══ ★1035 B-4（上行）══
       原则：WS 的 op **只是另一个入口**，真正的实现永远只有一份（RPC 的 case 分支）。
       这里全部转调 `dispatchMethod(method, payload)` —— 不复制任何业务逻辑，
       以后改 RPC 自动对两个入口同时生效。
       payload 里的 sessionId 用 op 的 sid 兜住：客户端不该在两处重复传同一个 id。 */
    const opViaRpc = async (method: string, sid: string, payload?: Record<string, unknown>) =>
      dispatchMethod(method, { ...(payload || {}), sessionId: sid })

    wsHub.onOp('stop', async (ctx) => {
      const r = await opViaRpc('session.cancel', ctx.frame.sid)
      ctx.ack({ ok: true, result: (r as unknown) ?? null })
    })
    wsHub.onOp('approve', async (ctx) => {
      const r = await opViaRpc('session.approval', ctx.frame.sid, ctx.frame.payload)
      ctx.ack({ ok: true, result: (r as unknown) ?? null })
    })
    wsHub.onOp('answer', async (ctx) => {
      const r = await opViaRpc('session.questionAnswer', ctx.frame.sid, ctx.frame.payload)
      ctx.ack({ ok: true, result: (r as unknown) ?? null })
    })
    wsHub.onOp('steer', async (ctx) => {
      /* ★1035：插话/追问。`session.steer` **只入队就返回**（不 await 整轮），
         所以它适合走 op，不像 prompt 那样需要两段式 ack。 */
      const r = await opViaRpc('session.steer', ctx.frame.sid, ctx.frame.payload)
      ctx.ack({ ok: true, result: (r as unknown) ?? null })
    })
    wsHub.onOp('resync', async (ctx) => {
      /* 只用于"客户端明确知道自己漏了"的对齐请求；增量 vs 快照由后端既有判定决定 */
      const r = await opViaRpc('session.resync', ctx.frame.sid, ctx.frame.payload)
      ctx.ack({ ok: true, result: (r as unknown) ?? null })
    })
    /* prompt / steer / upgrade-detail 暂不接：它们牵动发送主路径与乐观消息认领，
       需要和 1036（消息认领）一起验，不在这里半做。未注册的 op 会被 hub 报 internal（不静默成功）。 */

    // Subscription establishes the receiving connection's base; it is not a broadcast tick.
    wsHub.onSubscribe((conn, sid) => {
      const turn = sid && turnAccumulators.get(sid)
      if (turn) emitTurnSnapshot(sid, turn, false, false, conn)
    })
    wsHub.onConnectionReady((conn) => {
      if (!conn.hasStream('host')) return
      try {
        wsHub?.sendTo(conn, {
          v: PROTOCOL_V,
          stream: 'host',
          sid: '',
          kind: 'frame',
          payload: { type: 'host/workspace-changed', workspace: buildWorkspaceView() },
        })
      } catch (e) {
        console.error('[1035] 就绪补 workspace 失败:', String((e as Error)?.message || e))
      }
    })

    const wsSrc = process.env.NIS_WS === '1' ? 'env NIS_WS=1' : wsFlagFile
    console.log(`[1035] /api/ws 已挂载（来源: ${wsSrc}）—— 与 SSE 并存，前端连哪种由 ?transport= 决定`)
  }

  server.listen(PORT, PORT === 0 ? '127.0.0.1' : '0.0.0.0', () => {
    const address = server.address()
    if (!address || typeof address === 'string') throw new Error('Backend did not bind a TCP port')
    PORT = address.port
    /* ★1012d：若上次隧道是开启状态，启动后自动接回来 —— 用户不必每次重启后端都手点一次。
       ★P116：**推迟 6 秒再连**。启动瞬间有三件事同时拉外部进程：密钥解密（PowerShell，实测 10 秒）、
       隧道（ssh，实测 10 秒）、python 记忆内核（5 秒）—— 三个一起冲会互相抢 CPU/磁盘，
       表现为整个启动窗口里请求时快时慢。错开之后每个子进程独占资源，用户看到的"卡"明显减少。 */
    setTimeout(() => { void tryRestoreTunnel() }, 6000)
    const cfg = currentLlmConfig()
    console.log(`[pi-bridge] listening on http://127.0.0.1:${PORT}`)
    for (const u of lanUrls(PORT)) console.log(`[pi-bridge] LAN: ${u}`)
    console.log(`[pi-bridge] LLM: ${cfg.model} via ${cfg.providerName} (${cfg.base})`)
    /* ★1014f：PC 会话接管配对码 —— 手机（QQ/微信）私聊发「/pc <码>」即放行（仅私聊可配对，见 channels/pcAccess.ts） */
    try { getPairCode() } catch { /* 取码失败不挡启动 */ }
    /* ★1126：**重启后接回在跑的视频任务** —— 上游任务在服务端跑着，本地进程死了不等于任务死了。
       放在 listen 回调里（providers 已加载完），延迟 5 秒避开启动期的几路外部进程抢资源。 */
    setTimeout(() => {
      try { resumeVideoPolls() } catch (e: any) { console.warn('[bg] 恢复视频任务失败:', String(e?.message || e).slice(0, 120)) }
    }, 5000)
    console.log(`[pi-bridge] Ready for DSH frontend to connect`)
    /* ★P115：**启动期 CPU 采样器**（只在 `NIS_STARTUP_PROFILE=1` 时开）。
       为什么需要：启动那几秒的主线程堵塞靠日志只能看到"堵了多久"，看不到"谁在堵"；
       `--cpu-prof` 又要求进程正常退出（Windows 上被 kill 拿不到文件）。
       这里用 inspector 在**进程内**采 25 秒、到时自己 stop 并落盘，前端照常用，不需要退出。
       产物：`backend/data/_startup.cpuprofile`，用 `_prof_top.mjs` 解析（按自身采样数排序）。 */
    if (process.env.NIS_STARTUP_PROFILE === '1') {
      void (async () => {
        try {
          const inspector = await import('node:inspector')
          const session = new inspector.Session()
          session.connect()
          const post = (m: string) => new Promise<any>((res, rej) => session.post(m, (e: any, r: any) => (e ? rej(e) : res(r))))
          await post('Profiler.enable')
          await post('Profiler.start')
          console.log('[profile] 启动采样已开始（25 秒后自动停止并落盘）')
          setTimeout(async () => {
            try {
              const { profile } = await post('Profiler.stop')
              const out = path.join(DATA_ROOT, '_startup.cpuprofile')
              fs.writeFileSync(out, JSON.stringify(profile), 'utf8')
              console.log('[profile] 已落盘：' + out)
            } catch (e: any) { console.warn('[profile] 停止采样失败：', String(e?.message || e)) }
            finally { try { session.disconnect() } catch { /* ignore */ } }
          }, 25000)
        } catch (e: any) {
          console.warn('[profile] 采样未能启动：', String(e?.message || e))
        }
      })()
    }
    /* ★P114：**启动即异步预热供应商密钥** —— 那台子进程（编译 C# + DPAPI）要 2~3 秒，
       以前是"前端第一次调 providers.list 时才同步拉起" ⇒ 首屏那一刻整个后端被冻住。
       现在提前在后台跑，前端来的时候多半已经热了（最坏也只是 await 一个已在跑的 Promise）。 */
    void ensureProviderKeysWarmed()
    /* ★P118：**契约检查**（启动 60 秒后打一条汇总）——
       "骨架会话不该被顺手读正文"，正常只应是你真的打开过的会话各 1 次。
       数字异常（几十次以上）+ 栈来自 persist/定时器/遍历 ⇒ 有人违反了契约，日志会直接指出位置。 */
    setTimeout(() => {
      const n = skeletonBodyReads.length
      console.log(n === 0
        ? '[M2] 契约检查：启动 60 秒内没有"骨架期读正文"（正常）'
        : `[M2] 契约检查：启动 60 秒内读到 ${n} 次骨架正文（正常应只有你打开过的会话；下面是前 5 次的来源）`)
      for (const r of skeletonBodyReads.slice(0, 5)) console.log(`  · ${r.id} ← ${r.stack}`)
    }, 60000)
    /* ★ 0925e（需求要求"打开 NiusDream 自动获取 zen 的 free 模型"）：启动 8s 后静默同步
     * OpenCode Zen 公共档免费模型（拉列表 + 逐个探活，只放活的进模型表；6h 冷却）。
     * 延迟是让 providers 状态/网络栈先稳；失败静默，不挡任何功能。 */
    setTimeout(() => { void autoSyncZenFreeModels() }, 8000)
  })

  /* ── 0912 接入批：QQ 通道随服务启动 ──
   * 注册消息处理器（收到 QQ 消息 → 桥接到 NiusDream 会话）并按配置拉起所有已启用的机器人。
   * 配置变更时（channel.bot.* / channel.config.set）会再次 sync 重连。 */
  setQqBotHandlers({
    onMessage: (botId, ev) => {
      /**
       * 二十三批：**被回复的群消息也记一份流水**。
       * 之前只有「旁听」（全量事件里不回复的那批）进流水，@ 它并被回复的消息反而不在 ——
       * 下一轮被问「刚才聊了啥」时看不到「你刚问我什么」。同 messageId 自动去重。
       */
      if (ev.kind === 'group') {
        try {
          const lab = identifyMember('qq', ev.target, ev.senderId || ev.senderName || 'unknown', {
            name: ev.senderName,
            role: ev.senderRole,
          })
          const lineText = ev.content || (ev.images?.length ? '[图片]' : '') || (ev.files?.length ? '[文件]' : '')
          if (lineText) {
            recordGroupLine('qq', ev.target, {
              at: Date.now(),
              speakerId: ev.senderId || '',
              label: lab.label,
              role: lab.role,
              text: lineText,
              messageId: ev.messageId,
            })
          }
        } catch { /* ignore */ }
        // 插嘴冷静期：被 @ 正常回复也算「机器人刚说过话」（刚回完不该马上又插一句）
        try { markBotSpoke('qq', ev.target) } catch { /* ignore */ }
      }
      void handleChannelIncoming('qq', botId, ev.target, ev.content, {
        messageId: ev.messageId,
        kind: ev.kind,
        // 0912 十四批：发送者 + @列表（群聊场景让 AI 知道「谁在说话 / 在 @ 谁」）
        senderId: ev.senderId,
        senderName: ev.senderName,
        senderRole: ev.senderRole,
        mentions: ev.mentions,
        // 0912 二十一批：图片（已下载落盘）→ 附件喂给 agent（AI 能看图）
        images: ev.images,
        imageError: ev.imageError,
        // 0912 二十二批：非图片附件（文件）→ 挪进会话工作区，正文里给出路径（AI 用 fs_read 能读）
        files: ev.files,
      })
    },
    /**
     * 旁听到的群内全量消息（0912 十五批）—— **只记流水、不回复**。
     * 需群主在群设置里把「机器人可获取的群聊消息范围」改成「获取群内全部消息」。
     * 记下来的流水会在有人 @ 它时作为背景注入 → 于是「A 问 B 刚才说了什么」有答案。
     */
    onGroupMessage: (botId, ev) => {
      /* ★1014c：登记"该群最近的图"（只存地址、不下载）—— 紧接着有人 @ 它/它要插嘴时按需取用 */
      rememberGroupMedia('qq', botId, ev.target, ev)
      const label = identifyMember('qq', ev.target, ev.senderId || ev.senderName || 'unknown', {
        name: ev.senderName,
        role: ev.senderRole,
      })
      recordGroupLine('qq', ev.target, {
        at: Date.now(),
        speakerId: ev.senderId || '',
        label: label.label,
        role: label.role,
        text: ev.content,
        messageId: ev.messageId,
      })
      // 0912 二十四批：插嘴开关（默认关）—— 开着且过闸 → 主动搭一句
      void maybeInterjectInGroup(botId, ev, label.label).catch((e: any) => {
        console.warn(`[interject] 群 ${ev.target.slice(0, 8)} 插嘴失败: ${String(e?.message || e).slice(0, 160)}`)
      })
    },
    /**
     * 机器人被拉进群（0912 十六批）：立刻为这个群建好会话 + 打个招呼。
     *
     * 为什么必须建会话：被拉进群**不会**自动产生会话（要等有人 @ 它），
     * 于是 PC 端看不到这个群，用户容易误以为「几个群合并了 / 我加了他但没生效」。
     * 招呼走 `event_id` 事件被动回复，**不消耗**主动消息额度。
     */
    onGroupAdded: (botId, ev) => {
      if (!ev.groupOpenid) return
      // 真实群名（接口需白名单，失败就继续用 群A/群B）
      void syncGroupName('qq', botId, ev.groupOpenid)
      try {
        const sid = resolveChannelSession('qq', botId, ev.groupOpenid, `QQ 群 · ${ev.groupOpenid.slice(0, 6)}`, { kind: 'group' })
        if (sid) console.log(`[channel] 入群事件：已为该群准备会话 ${sid.slice(0, 8)}`)
      } catch (e: any) {
        console.warn(`[channel] 入群建会话失败: ${String(e?.message || e).slice(0, 150)}`)
      }
      const botName = qqBotStatus()[botId]?.nickname || ''
      const greet = `大家好，我是「${botName || '本群机器人'}」。需要我时 @ 我一下就行 —— 我能查资料、回答问题，也能把文件或图片发到群里。`
      void sendQqMessage(botId, { kind: 'group', target: ev.groupOpenid, messageId: '', eventId: ev.eventId }, greet)
        .catch((err: any) => console.warn(`[channel] 入群打招呼失败: ${String(err?.message || err).slice(0, 150)}`))
    },
    onStatus: (botId, st) => {
      console.log(`[channel] QQ bot ${botId} 状态: ${st.connected ? '已上线' : '离线'}${st.error ? ' · ' + st.error : ''}`)
      /* ★1126 修（老板实测「对话跑着头像会回退成 logo，过会儿又变回来」）：
         这里原来发的是 `host/settings-updated`，但 settings **只带 __channelStatus 一个字段**。
         前端 applyBackendSettings 会把它当一次完整同步、把帧里没有的 `avatarVersion` 清空
         ⇒ nisAvatar 回落到默认 logo，直到下一次全量广播才恢复 —— 头像闪烁的真因。
         窄帧必须走窄事件：设置通道只承载"整份设置"。前端目前还没有这条事件的消费方
         （将来做通道弹窗时按这个事件名接），所以这里只保留推送意图、不再污染 settings。 */
      broadcastHost({ type: 'host/channel-status', status: { qq: qqBotStatus() } } as any)
    },
  })
  syncQqBotsFromConfig().catch((e: any) => {
    console.warn(`[channel] 启动 QQ 机器人失败（不拦启动）: ${String(e?.message || e).slice(0, 200)}`)
  })

  /* ── 微信（官方 ClawBot / iLink）：长轮询收 + sendmessage 发 ── */
  setWechatBotHandlers({
    onMessage: (botId, ev) => {
      void handleChannelIncoming('wechat', botId, ev.target, ev.content, {
        messageId: ev.messageId,
        kind: ev.kind,
        contextToken: ev.contextToken,
        // 0912 二十一批：图片（CDN 解密后落盘）→ 附件喂给 agent（AI 能看图）
        images: ev.images,
        imageError: ev.imageError,
      })
    },
    onStatus: (botId, st) => {
      console.log(`[channel] 微信 bot ${botId} 状态: ${st.connected ? '已连接' : '断开'}${st.error ? ' · ' + st.error : ''}`)
      /* ★1126：同上 —— 窄帧走 `host/channel-status`，不再冒充设置更新（否则每次微信上下线都会清空头像指纹）。 */
      broadcastHost({ type: 'host/channel-status', status: { wechat: wechatBotStatus() } } as any)
    },
  })
  try { syncWechatBotsFromConfig() } catch (e: any) {
    console.warn(`[channel] 启动微信连接失败（不拦启动）: ${String(e?.message || e).slice(0, 200)}`)
  }

  /* ── 定时任务（0912 十二批）+ 通道推送 / 专属会话（十三批）── */
  /**
   * 定时任务 × 模型选择（0912 需求）。
   *   · task.modelMode='global'（默认）→ 跟随「设置 → 人格 → 全局模型」；
   *       **全局模型未选 → 直接报错**（不静默兜底用别的模型）。
   *   · task.modelMode='custom' → 用 task.modelId / modelProviderId 指定的模型；
   *       该模型/供应商已失效 → 也直接报错（绝不悄悄换成全局模型）。
   *
   * 为什么在 runner 里切而不是建会话时切：专属会话是跨次复用的，用户可能中途改了任务模型，
   * 每次执行都按**当前**任务配置重新钉一遍，保证"任务卡片上写的模型 = 实际用的模型"。
   */
  function applyTaskModel(task: any, sessionId: string): void {
    const s = sessions.get(sessionId)
    if (!s) return
    const name = String(task?.name || '定时任务')
    const mode = task?.modelMode === 'custom' ? 'custom' : 'global'
    if (mode === 'global') {
      /* ★1013（已定案："以前可以选用全局模型的，都要换成后台模型"）：定时任务的「全局」档改读
         **后台模型**（不再用聊天全局值）。未配置 / 供应商不可用 ⇒ 直接报错，不做任何兜底。 */
      const cfg = backgroundLlmConfig()
      if (!cfg.configured || !cfg.base || !cfg.model) {
        throw new Error(`定时任务「${name}」执行中止：${cfg.reason || '未配置「后台模型」'}。请到「设置 → 人格 → 后台模型」选一个。`)
      }
      const prov = getState().providers.find(x => x.id === cfg.providerId)
      if (!prov?.base) {
        throw new Error(`定时任务「${name}」执行中止：后台模型「${cfg.model}」的供应商已失效，请重新选择。`)
      }
      s.model = cfg.model
      s.modelProviderId = cfg.providerId
      /* ★1003 安全批 4.78 核实结论：明文 apiKey 只进**内存**的 llmOverride（1001 请求期设计）——
         出口已全封：①buildSessionPayload 白名单不含 llmOverride 值（0929 起只落 llmOverrideBy 标记）；
         ②session.list / session.history 均为显式字段表，不带 llmOverride；③运行时无整对象序列化会话。
         审计说的"schedulePersist 落盘泄密"前提已过时。2.0 内嵌模式应改为"请求期按 providerId 现解"，
         彻底不落明文；在那之前别把 llmOverride 加回任何持久化/响应字段表。 */
      s.llmOverride = {
        providerId: prov.id,
        providerName: prov.name || prov.id,
        base: endpointBase(prov.base, prov.protocol),
        apiKey: plainKeyById(prov.id),          // ★ 1001：取明文（定时任务发请求同样不能带密文）
        model: cfg.model,
        protocol: prov.protocol || 'openai-completions',
        // F轮：全局模型任务同时带上全局推理强度（cfgs.effort 已按模型钳过）
        effort: cfg.effort ?? null,
      }
      s.llmOverrideBy = 'user'
      schedulePersist()
      return
    }
    // custom：必须指定到具体模型，且供应商必须还在
    const mid = String(task?.modelId || '').trim()
    const pid = String(task?.modelProviderId || '').trim() || resolveModelProviderId(mid) || ''
    if (!mid || !pid) {
      throw new Error(`定时任务「${name}」执行中止：任务选了「自选模型」但没指定具体模型，请重新编辑任务。`)
    }
    const prov = getState().providers.find(x => x.id === pid)
    if (!prov?.base) {
      throw new Error(`定时任务「${name}」执行中止：自选模型的供应商「${pid}」已不存在，请重新选择。`)
    }
    const has = (getState().providers.find(x => x.id === pid)?.models || []).some(m => m.id === mid && m.enabled !== false)
    if (!has) {
      // 模型表可能为空（新供应商未拉取）→ 仍允许，交给后端调用时报错，但给出明确日志
      console.warn(`[scheduledTasks] 「${name}」自选模型 ${pid}/${mid} 不在已启用模型表中，按字面使用`)
    }
    s.model = mid
    s.modelProviderId = pid
    s.llmOverride = {
      providerId: prov.id,
      providerName: prov.name || prov.id,
      base: endpointBase(prov.base, prov.protocol),
      apiKey: plainKeyById(prov.id),          // ★ 1001：取明文
      model: mid,
      protocol: prov.protocol || 'openai-completions',
      // F轮：自选模型也可带推理强度（任务级 effort，按该模型钳位；空 = 跟随模型默认）
      effort: clampEffort(pid, mid, task?.modelEffort ?? null),
    }
    s.llmOverrideBy = 'user'
    schedulePersist()
  }

  /* ── 0920：后台任务接线 ──
     ① emitter：任务进度/状态变化 → 广播 host 帧（前端胶囊 tab + 任务视图）
     ② notifier：任务结束 → ① 会话内联提示（用户看得见）② 通知"派它的那轮 AI"：
        agent 正在跑就 steer 进去（注入点=当前轮工具批次跑完），没跑就记 pending、下轮开跑时补。 */
  setBgEmitter((t) => {
    try {
      const payload: any = { type: 'bg/updated', task: JSON.parse(JSON.stringify(t)) }
      const _bgConv = String(t.conversationId || '')
      /* ★ 0922c 修（实测：计划卡正常、后台任务要切对话才出现）：
         原来发 broadcastHost → /api/events.host 的 hostClients，而**前端从未连过该端点**
         （只连 /api/events.mux）⇒ 帧全丢，只能靠切会话时 bg.list 拉取补上。
         改走 mux（与计划卡同一条路）：有归属会话发该会话订阅者，否则发全量桶。 */
      if (_bgConv) broadcastMux(_bgConv, payload)
      else broadcastMux('', payload)
    }catch (e) { /* ignore */ swallowedThrottled('broadcast', e, 'bg/updated|' + String(t.conversationId || '')) }
  })
  /* ★ 0922e：进程监控 —— 注册表变更 → mux 广播（前端「进程」面板实时增删；
   设计口径：只显示正在运行的，结束就消失）。有归属会话就发该会话订阅者，否则发全量桶。
   ★第十三轮：这里**只负责发布**。原来它兼做落库（按成员 ID 猜 attempt）且 catch 吞错 ——
   落库已移到工具启动层（见下方 `setProcRegistrar`），身份由启动层带下来。 */
setProcEmitter((p) => {
  try {
    const payload: any = { type: 'proc/updated', proc: JSON.parse(JSON.stringify(p)) }
    const _procConv = String((p.origin && p.origin.conversationId) || '')
    if (_procConv) broadcastMux(_procConv, payload)
    else broadcastMux('', payload)
  }catch (e) { /* ignore */ swallowedThrottled('broadcast', e, 'proc/updated|' + String((p.origin && p.origin.conversationId) || '')) }
})
/* ★第十三轮：**持久登记**（工具生命周期内，不在广播回调里）。
   身份来自 `origin.team` —— 开工边沿绑定的确切 attempt，不再从成员会话反推。
   失败处置写在这一处（唯一策略点）：
     · 能挂围栏 ⇒ 挂持久围栏（这一步本身就是"副作用状态未知"的持久事实，会挡住所有后单）；
     · 连围栏都写不进 ⇒ 进阻断态 `blockToolsRegistrationFailed`（fail-closed：证明不了就不许开工），
       并把原文留成可见证据（error 日志 + stageReport）。 */
setProcRegistrar((p, phase) => {
  /* ★1123（老板）：成员可以挂后台长任务 —— bg_start 拉起的进程**不进团队账本的围栏表**：
     它是有意的、有 task_id 可管理的后台任务，不是"工具执行的未确认副作用"。
     它照样进 processRegistry（进程监控可见）与 bgList（按任务管理）；崩溃恢复靠这两处发现它。 */
  if (p.origin?.tool === 'bg_start') return
  const team = p.origin?.team
  if (!team) return                       /* 非团队执行：没有账本可记，普通会话零影响 */
  const parent: any = team.hostSessionId ? sessions.get(team.hostSessionId) : null
  const host = parent?.teamId ? teamV2HostFor(parent) : undefined
  if (!host) {
    /* 宿主没了（会话被删/已不是团队）⇒ 这条 pid 无处登记。不是"没有残留"，而是"没有账本能证明它"，
       如实留一条 error，供人工按 pid 处置；不假装成功。 */
    try { console.error(`[团队V2] 工具进程 pid ${p.pid} 无法登记：团队账本宿主已不存在（attempt #${team.attemptId}）`) } catch { /* ignore */ }
    return
  }
  host.noteToolProcess(team, p, phase)
  /* ★1124：pid 一拿到就把**启动意图**补成"已知 pid"（同一件事的两个阶段）。
     补不上由 host 留痕；意图行留在"pid 未知"状态就会让这一单按未确认副作用处理（保守方向）。 */
  if (phase === 'spawned' && p.origin?.intentToken) host.bindProcIntent(team.attemptId, String(p.origin.intentToken), Number(p.pid))
})
/* ★1124：**启动意图**（`spawn()` 之前，pid 还不存在）。
   身份来源与 registrar 完全相同（`origin.team`，开工边沿绑定），只是发生得更早。
   返回的 token 由工具层带进 origin：拿到 pid 后补回同一行，进程结束删行。 */
setProcIntentHook({
  begin: (origin) => {
    const team = origin?.team
    if (!team) return null                        /* 非团队执行：没有账本可写，普通会话零影响 */
    if (origin.tool === 'bg_start') return null   /* 有意后台任务不进团队账本（与 registrar 同口径） */
    const parent: any = team.hostSessionId ? sessions.get(team.hostSessionId) : null
    const host = parent?.teamId ? teamV2HostFor(parent) : undefined
    if (!host) {
      try { console.error(`[团队V2] 工具启动意图无法落库：团队账本宿主已不存在（attempt #${team.attemptId}）`) } catch { /* ignore */ }
      return null
    }
    const token = `${team.hostSessionId}#${crypto.randomUUID()}`
    try {
      /* 这单已结算（不是 queued/running）⇒ 不落意图、也不伪造：返回 null，pid 仍走常规登记。 */
      return host.beginProcIntent(team.attemptId, token, String(origin.tool || 'run_command')) === null ? null : token
    } catch (error) {
      /* 账本写不进 = 证明不了副作用状态 ⇒ fail-closed：先挂持久围栏；围栏都写不进就抛，
         让这轮工具失败（模型看得见），绝不静默当成"没问题"。 */
      const text = `工具启动意图写入失败（attempt #${team.attemptId}，tool ${String(origin.tool || 'run_command')}）：${String((error as Error)?.message || error).slice(0, 300)}`
      try {
        host.ledger.holdFence(team.requestId, team.attemptId, `${text}；副作用状态未知，必须先确认清理才放行`)
        try { console.error(`[团队V2] ${text}（已挂持久围栏）`) } catch { /* ignore */ }
        return null
      } catch (fenceError) {
        throw new Error(`${text}；围栏也写不进：${String((fenceError as Error)?.message || fenceError).slice(0, 200)}`)
      }
    }
  },
  end: (token) => {
    const text = String(token || '')
    const cut = text.indexOf('#')
    if (cut <= 0) return
    const parent: any = sessions.get(text.slice(0, cut))
    const host = parent?.teamId ? teamV2HostFor(parent) : undefined
    /* 删不掉就留着：残留意图会让这一单被当成"未确认副作用"挡住（保守方向，不是掩盖）。 */
    host?.endProcIntent(text)
  },
})
setProcRemover((p) => {
  try {
    /* 阶段4补正：成员会话里的工具进程退出，可能正是围栏等的那件事 ⇒ 让父团队会话复核一次。 */
    const _pc: any = p.origin?.conversationId ? sessions.get(String(p.origin.conversationId)) : null
    const _pp: any = _pc?.parentSessionId ? sessions.get(String(_pc.parentSessionId)) : null
    if (_pp && _pp.teamId) teamV2HostFor(_pp)?.kickFenceRecheck()
  } catch { /* ignore */ }
  try {
    const payload: any = { type: 'proc/removed', id: p.id, pid: p.pid }
    const _procConv = String((p.origin && p.origin.conversationId) || '')
    if (_procConv) broadcastMux(_procConv, payload)
    else broadcastMux('', payload)
  }catch (e) { /* ignore */ swallowedThrottled('broadcast', e, 'proc/removed|' + String((p.origin && p.origin.conversationId) || '')) }
})
setBgNotifier((t) => {
    const convId = String(t.conversationId || '')
    /* 阶段4补正：成员会话的后台任务结束，可能正是围栏等待的那个副作用交还了 ⇒
       立刻让它的父团队会话复核一次（只在该父会话确实挂着围栏时才动作）。 */
    try {
      const child: any = convId ? sessions.get(convId) : null
      const parentId = String(child?.parentSessionId || '')
      const parent: any = parentId ? sessions.get(parentId) : null
      if (parent && parent.teamId) teamV2HostFor(parent)?.kickFenceRecheck()
    } catch { /* 复核失败不影响通知本身 */ }
    if (!convId) return
    const head = t.status === 'completed' ? '后台任务完成' : t.status === 'cancelled' ? '后台任务已取消' : '后台任务失败'
    const body = String(t.result || t.error || '').slice(0, 600)
    const note = `${head}：「${t.title}」\n${body}`
    /* ★ 0923（实测反馈：『内联通知一下一大串』）：**用户可见**的会话提示只给一句话摘要
       —— 任务完整输出在后台任务胶囊/详情弹窗里点开就看得到，别把 600 字结果铺在时间线上。
       给 AI 的 note 仍保持完整（模型需要细节，且前端对注入类消息已默认折叠成一行）。 */
    const brief = String(t.result || t.error || '').replace(/\s+/g, ' ').trim()
    const userLine = `${head}：「${t.title}」` + (brief ? ` · ${brief.slice(0, 60)}${brief.length > 60 ? '…' : ''}` : '')
    const pushUserLine = () => {
      /* ★1022au（1022at 之后仍无提示，`noticeLog` 实测为 0 —— 说明这里曾经**静默失败**过）——
         原来整段包在一个 try / catch 里（catch 是空的）：任何一步抛错（比如 currentTurnBaseId
         在无 agent 状态下取值、或 sessions.get 拿不到会话）都会**悄悄跳过全部三步**，用户侧表现就是
         "什么都没有"。这不叫稳，叫掩盖。
         这里拆成三步各自兜住并**留痕**：noticeLog 一定写、broadcast 一定发，哪一步失败日志里看得见。 */
      const at = Date.now()
      /* ★1022az（减法收口）：通知**只写一次 noticeLog**，不碰 sequence、不设 pending。
         为什么这样最干净：通知不属于任何一轮，它是"轮与轮之间的独立事件"。
         实时显示由前端按 `notice:<ts>` 幂等追加一条横幅；刷新由 `buildTurns` 用**同一个 id** 重建
         ⇒ 两条路同一个身份，合并时按 id 命中，天然不会重复，也不会把轮结构搅乱。 */
      /* ★1023h/o：定位**只认锚点**（afterToolId = 触发它的那条工具调用的 id）——
         锚在具体的一块上，后面的思考/正文再多也顶不动它，工具 id 落盘不变 ⇒ 刷新后位置一致。
         （原来还有一条"块序号 atBlock"的退路，与锚点两套口径 ⇒ 实时/刷新位置对不上，已删。） */
      /* ★1023l（老大反复实测"那条 think 跑到通知上面去了"）——
         光有块序号不够：通知发生的瞬间，模型可能刚封口了一段思考，序号就会落在它后面。
         语义上这条通知属于"**你挂的那个后台任务**"，所以锚定**触发它的那条工具调用块**
         （`afterToolId` = 本轮最后一条 tool 的 callId）。前端按它定位 ⇒ 永远紧跟命令那一行，
         后续无论多少思考/正文都不会把它顶走；工具 id 在落盘后不变 ⇒ 刷新后位置也一样。 */
      /* ★1024bd（结构性修复，不是兜底）：通知的定位锚点 = **挂这个任务的那条工具调用**。
         原来这里去"当前累加器里找最后一个 tool_use" —— 后台任务往往是**上一轮**挂的，
         完成时累加器里根本没有它（甚至已被 agent_end 删掉）⇒ 锚点为空 ⇒ 通知掉到本轮正文末尾，
         AI 继续写它就一路往下走（实测）。任务在创建时已把 callId 记进 `spawnedByCall`，
         这里直接取用；老任务（没这个字段）拿不到锚点就落轮末 —— 那是**真实缺数据**，不是猜。 */
      const _afterToolId = String((t as any).spawnedByCall || '')
      /* ★1024bf（**后端为唯一源 · 段归属**）：通知到底属于"某一段回复内部"还是"段与段之间"，
         后端是唯一知道的地方 —— 判据是**当前是否有正在写的段、且它已经有内容**：
           · 有内容 ⇒ 这次 agent 已经在输出了 ⇒ 通知是"这一轮里发生的事件"，归该段内按时间落位；
           · 没有（连累加器都没有 / 刚开新段还没吐字）⇒ 上次回复**已经收尾**，通知是**段与段之间的
             独立事件**，该落在上一段（含它的统计行）之后，后续新回复自然另起一段。
         前端不再做任何时间推断。`afterSegId` = 段 id（就是那条 assistant 消息 id）。 */
      const _acc: any = turnAccumulators.get(convId)
      const _hasWork = !!(_acc && (String(_acc.text || '').trim() || String(_acc.reasoning || '').trim() || (Array.isArray(_acc.sequence) && _acc.sequence.length > 0)))
      const _standalone = !_hasWork
      /* ★1024bh（**通知应该落在"两段之间"**，实测）：`standalone` 通知是"上一段已收尾之后"的独立事件，
         它的归属段必须是**上一段（已落盘的那条 assistant 消息）**，而不是"当前正在写的那一段" ——
         否则任务完成时新一轮已经开跑，通知会被归到新段、显示在新段**之后**（看起来像"又跑到最后"）。
         取法：`session.messages` 里倒序最后一条带 id 的 assistant 消息 = 上一段（当前段还没落盘）。
         段内通知（`_hasWork`）仍归当前累加器。 */
      let _segId = String(_acc?.id || '')
      /* ★1026l（**补全权威归属：段 → 轮**）——实测（老大）：实时位置正确、**刷新后掉到页底**。
         差异只有一个：刷新后 turns 只加载**最后 N 轮**（实测 11 轮只给 5 个），若锚点段落在未加载的
         更早轮里，前端 `segOwner` 命中不了 ⇒ 兜到 `lastTurnId` ⇒ 堆到页底。
         这里补 `afterTurnId`（段所属**轮** id = 该轮首条 user 消息 id，落盘不变）：
         前端先用它命中轮；仍命中不了 ⇒ 该轮更早、没加载 ⇒ 插到「已加载的最早一轮之前」。
         窗口只含最后 N 轮 ⇒ "没加载的轮一定更早"是**窗口语义的必然**，不是猜。 */
      let _segTurnId = String(currentTurnBaseId(convId) || '')
      if (_standalone) {
        const _msgs = Array.isArray((sessions.get(convId) as any)?.messages) ? ((sessions.get(convId) as any).messages as any[]) : []
        _segId = ''
        for (let i = _msgs.length - 1; i >= 0; i--) {
          const mm = _msgs[i]
          if (mm?.role === 'assistant' && mm.id) {
            _segId = String(mm.id)
            /* 该段所属轮 = 它前面最近的 user（注入消息用 `injectedTurnId`，与 `buildTurns` 同口径）
               ★1126 纠偏（**老板实测"后台任务完成通知直接没显示"**）：
               注入消息的 id 是 `inj-…`，而前端**不为注入轮建节点**（`turnIds` 里没有它）
               ⇒ 把它当 `afterTurnId`，这条通知就永远命中不了、静默不渲染。
               正确做法：**跳过注入消息，继续往前找真实用户消息** —— 通知归到它真正发生的那一轮。
               这是结构性修正，不是兜底：锚点必须指向前端真实存在的轮，否则它就没有位置。 */
            for (let j = i - 1; j >= 0; j--) {
              const uu: any = _msgs[j]
              if (uu?.role !== 'user') continue
              if (isInjectedUserMsg(uu)) continue
              if (uu.id) { _segTurnId = String(uu.id); break }
            }
            break
          }
        }
      }
      const _noticeRec = { text: userLine, ts: at, afterToolId: _afterToolId, afterSegId: _segId, afterTurnId: _segTurnId, standalone: _standalone }
      try {
        const s = sessions.get(convId)
        if (s) {
          const arr = (((s as any).noticeLog) ||= [] as any[])
          arr.push(_noticeRec)
          if (arr.length > 200) arr.splice(0, arr.length - 200)
          schedulePersist()
        } else {
          sessionLog(convId, 'warn', 'lifecycle', '内联通知没找到会话对象（noticeLog 未记录，刷新后该条会丢）')
        }
      } catch (e: any) {
        sessionLog(convId, 'warn', 'lifecycle', `内联通知写 noticeLog 失败：${String(e?.message || e).slice(0, 120)}`)
      }
      sessionLog(convId, 'info', 'lifecycle', `内联通知已记录（ts=${at}）：${userLine.slice(0, 60)}`)
      /* ★1023e（实测"后台任务完成播报完全没了"）——
         上一批改造把两处显示都拿掉了：① 注入消息（【后台任务完成】…）不再渲染（这是对的，它冒充用户说话）
         ② `notices[]` 横幅被删（那是"同一条通知画两遍"的来源）。结果这条**只写进 noticeLog、没有广播**
         ⇒ 实时完全看不到，刷新也没人渲染。
         正确的位置：**当轮末尾的一行过程提示**（`session-notice` 通道，前端已支持），
         不冒充消息、不进正文、不占轮次。用户要的是"知道它跑完了"，不是"流里多一条假消息"。 */
      try {
        broadcastMux(convId, { type: 'session/projection', sessionId: convId, key: 'session-notice', seq: Date.now(), value: { text: userLine, at, afterToolId: _afterToolId, afterSegId: _segId, afterTurnId: _segTurnId, standalone: _standalone } } as any)
      }catch (e) { /* 广播失败不影响收尾：noticeLog 仍在，日志可查 */ swallowedThrottled('broadcast', e, 'session/projection|' + String(convId)) }
    }
    /* ★1124x（**自动续跑已拆除**）：这里原来是两条路 —— `scheduleBgResume`（忙时排队、**本轮结束自动开新轮**）
       与"记待办"。老板实测的问题就出在第一条：AI 正文已经说完，收轮后又冒出一段，计时/用量从 0 重算。
       现在统一走**与团队回归同构**的投递口径 `injectSessionNotice`：
         · AI 空闲（mainRunning=false）⇒ 开一轮把结果带走（老板认可，保留）；
         · AI 正忙 ⇒ 只入 inbox，下一次任何轮次开始前由 `drainBgNotices` 带给模型；
       用户可见通知照发（`pushUserLine` → session-notice / noticeLog），与上面那段分工不变。 */
    t.notified = true
    pushUserLine()
    try {
    /* ★1124v：**不加任何前缀** —— 前端段首横线只在 `noticeLabel` 非空时才画
       （`INJECT_MARKERS` 里 `bg_resume` 的 label 本来就是空的，就是这个道理）。
       前缀一加，对话流里就多一条「后台任务通知」横线（老板截图否掉的那条）。
       模型照样看得懂正文（`后台任务完成：…`），用户看的是那一行 `session-notice` 小字。 */
      /* ★1126 纠偏（**1124v 那步把 bug 引回来了**）：前缀不是"装饰"，它是 `isInjectedUserMsg` 的
         **身份判据** —— 删掉它，这条消息就认不出是注入，走普通 user 分支落盘 ⇒ 前端画成
         用户气泡（老板实测：视频任务完成后多出一条蓝色"用户消息"）。
         而 `_inject` 的补写又发生在 `if (isInjectedUserMsg(msg))` **内部** ⇒ 靠它进门、进门才补它，死锁。
         ⇒ 前缀必须保留（身份），横线由 `INJECT_MARKERS` 的 label 控制（已把 bg_notice 的 label 置空，
         前端"无标签无头像 ⇒ 不画段首"，效果与 1124v 想要的一致，但身份不再丢）。 */
      injectSessionNotice(convId, `【后台任务通知】${note}`)
      sessionLog(convId, 'info', 'lifecycle',
        `${head}：${t.title}（已投递给模型：${(sessions.get(convId) as any)?.mainRunning === true ? '主 agent 正忙 → 就地喂进本轮，做完手头的事一并处理' : '空闲 → 开一轮'}）`)
    } catch (e: any) {
      const q = pendingBgNotices.get(convId) || []
      q.push({ text: note })
      pendingBgNotices.set(convId, q.slice(-10))
      sessionLog(convId, 'warn', 'lifecycle', `${head}：${t.title}（投递失败转待办：${String(e?.message || e).slice(0, 120)}）`)
    }
  })

  /* ★ 0922：AI 自约定的「后台回访」——到点把任务现状推回给 AI。
     正在跑 → steer 插话（不打断）；空闲 → 按设置自动拉起一轮（bgWatchAutoWake，默认开）；
     设置关掉 → 只记待办，等下次开跑时补送（省 token 的保守档）。 */
  setBgWatcher(async (w) => {
    const convId = w.conversationId
    const list: any[] = w.taskId
      ? [bgGet(w.taskId)].filter(Boolean)
      : bgList(convId).filter((t) => t.status === 'background' || t.status === 'paused')
    const body = list.length
      ? list.map((t: any) => {
        const prog = t.progress?.percent >= 0 ? `${Number(t.progress.percent).toFixed(0)}%` : (t.progress?.note || '')
        const tail = (t.output || []).slice(-4).join('\n')
        return `「${t.title}」${t.status}｜${prog}${tail ? '\n' + tail : ''}`
      }).join('\n---\n')
      : '（没有在跑的后台任务了 —— 可能已结束，用 bg_list 看结果）'
    /* ★ 0922c-7：带上"第几次 + 建议下次多久"，并把"结束会自动通知"讲明白（防 AI 反复自唤醒） */
    const nextHint = w.taskId ? `；若还要盯，建议下次 ${bgSuggestWatchSec(w.taskId)} 秒` : ''
    const text = `【后台任务回访${w.seq ? ` · 第 ${w.seq} 次` : ''}】${w.note ? `你约的回访（备忘：${w.note}）\n` : ''}${body}\n（要看完整输出用 bg_read${nextHint}。任务结束会自动通知你，别反复轮询。）\n（若这次看到**失败**：能自愈就重试一次并说明；需要用户拍板、或同一任务已失败两次 → 停下来用 ask_user 问用户。）`
    /* ★0930（需求要求"回访别百分百打扰，让 LLM 根据情况决定"）：叫醒前先过轻量 LLM 裁决 ——
       任务失败/卡住/报错/要决策才叫醒 AI；一切正常就不打扰（任务结束会自动通知，信息不丢）。
       裁决失败/超时 → 保守放行。 */
    const verdict = await judgeBgWorthWaking(convId, text)
    if (!verdict.need) {
      sessionLog(convId, 'info', 'lifecycle', `后台回访（LLM 裁决跳过，不打扰）：${w.note || '看进度'} —— ${verdict.reason}`)
      return
    }
    sessionLog(convId, 'info', 'lifecycle', `后台回访（LLM 裁决放行）：${verdict.reason}`)
    /* ★1124x（自动续跑已拆除）：这里原来先走 `scheduleBgResume`（忙时排队、本轮结束自动开新轮），
       它一接管就直接 return ⇒ 后面的"忙进待办 / 关掉则不打扰 / 空闲开一轮"三条分支形同虚设。
       现在删掉那一行，回访自己的三分支本来就已经是正确形态（忙→inbox、设置关→inbox、空闲→开一轮）。 */
    const agent = agents.get(convId)
    /* ★1020（活跃口径统一）：同上一处 —— 用 sessionAgentBusy() 判"在不在跑"，别只看文本流。 */
    const streaming = sessionAgentBusy(convId)
    if (streaming) {
      const q = pendingBgNotices.get(convId) || []
      q.push({ text })
      pendingBgNotices.set(convId, q.slice(-10))
      sessionLog(convId, 'info', 'lifecycle', `后台回访（AI 正忙，挂起记待办不打断）：${w.note || '看进度'}`)
      return
    }
    if (globalSettings.bgWatchAutoWake === false) {
      const q = pendingBgNotices.get(convId) || []
      q.push({ text })
      pendingBgNotices.set(convId, q.slice(-10))
      sessionLog(convId, 'info', 'lifecycle', `后台回访（设置关了自动唤醒 → 记为待办）：${w.note || '看进度'}`)
      return
    }
    /* 空闲 → 主动把 AI 叫起来跑一轮（走与手打消息同一条路，输出自然落进会话） */
    sessionLog(convId, 'info', 'lifecycle', `后台回访（自动唤醒 AI 跑一轮）：${w.note || '看进度'}`)
    void runPromptCore(convId, { message: text, source: 'notice' }).catch((e: any) => {
      console.warn('[bg] 回访自动唤醒失败:', e)
      const q = pendingBgNotices.get(convId) || []
      q.push({ text })
      pendingBgNotices.set(convId, q.slice(-10))
      sessionLog(convId, 'warn', 'lifecycle', `回访自动唤醒失败（转待办）：${String(e?.message || e).slice(0, 120)}`)
    })
  })

  setTaskRunner(async (task: any, sessionId: string) => {
    // 模型口径（0912）：按任务配置钉死；配置有问题就抛错，任务会被标 error 并把原因写进会话
    applyTaskModel(task, sessionId)
    // 与手打消息同一条路径 —— 结果自然落进会话，打开对话就能看到
    /* ★1124y：任务标题是**给模型看的上下文**，不进 message（否则落盘/气泡里带着 `[定时任务「…」· 每天 09:00]`） */
    const modelContext = `[定时任务「${task.name}」· ${describeSchedule(task.schedule)}] `
    /* ★0927 P0-1：定时任务**要本轮结果**才敢往下走（后面还要推通知）→ 忙时等空闲再发（blocking 语义不变）；
       等不到（超 10 分钟）自动转队列，消息不丢。 */
    await runPromptCore(sessionId, { message: String(task.prompt || ''), modelContext, __busyPolicy: 'wait', source: 'notice' })
    /**
     * 执行完 → 按配置推结果到微信 / QQ 机器人。
     * 推送失败只记日志（在 notifyTaskResult 内部 catch），**不影响任务状态** ——
     * 否则 IM 掉线会把任务标成 error，用户以为任务本身跑挂了。
     */
    const targets = normalizeNotifyTargets(task.notifyTargets)
    if (targets.length) await notifyTaskResult(task, sessionId, targets)
    return { sessionId }
  })
  setTaskSessionResolver((task: any) => {
    const mode = String(task.targetSessionId || '').trim()
    const targets = normalizeNotifyTargets(task.notifyTargets)
    // ① 用户显式指定了某条会话，且它还在 → 就用它
    if (mode && mode !== 'own' && mode !== 'new' && sessions.has(mode)) return mode
    /**
     * ② 默认：任务专属会话。
     * 有通知目标时，**执行落点 = 首个目标的专属会话**；其余目标各自另有一条
     * （推送时建，见 notifyTaskResult）→ 各通道历史互不可见（0912 十七批）。
     */
    if (mode !== 'new') {
      const sid = ensureTaskOwnSession(task, targets[0])
      try { setExecSession(String(task?.id || ''), sid) } catch { /* ignore */ }
      return sid
    }
    // ③ 每次新建（用户显式选了这个模式）
    const s = createSession(`定时任务 · ${task.name}`)
    console.log(`[scheduledTasks] 为「${task.name}」新建会话 ${s.id.slice(0, 8)}`)
    return s.id
  })
  try { startScheduler() } catch (e: any) {
    console.warn(`[scheduledTasks] 启动失败（不拦启动）: ${String(e?.message || e).slice(0, 150)}`)
  }

  /**
   * 启动后把已知群的真实群名同步一遍（0912 十八批）。
   * 延后 25s：等各通道机器人连上（拿不到 token 就调不了接口）。
   * 拿到真群名 → 「群A」自动变成群名；拿不到（无白名单权限）就维持 群A/群B，不影响功能。
   */
  setTimeout(() => {
    try {
      const seen = new Set<string>()
      for (const [_k, v] of Object.entries(listLinks())) {
        if (v?.channel !== 'qq' || !v.peerId || (v.kind || '') !== 'group') continue
        const key = `${v.botId}:${v.peerId}`
        if (seen.has(key)) continue
        seen.add(key)
        void syncGroupName('qq', v.botId, v.peerId)
      }
      if (seen.size) console.log(`[channel] 启动群名同步：${seen.size} 个群`)
    } catch { /* ignore */ }
  }, 25_000)
})

// A1.3 进程信号处理：退出前尽量把会话落盘（防"退出即丢最后 500ms"）。
// 只 graceful 持久化后退出；unhandledRejection 记日志不退出（与"局部 catch 不中断服务"哲学一致）
let exiting = false
function gracefulExit(sig: string): void {
  if (exiting) return
  exiting = true
  console.log(`[pi-bridge] ${sig} received, flushing sessions…`)
  try { stopAllQqBots() } catch { /* 关闭通道不阻塞退出 */ }
  // 微信：发下线通知（手机端立刻显示离线）+ 停轮询
  try { stopAllWechatBots({ notify: true }) } catch { /* ignore */ }
  try { persistSessionsSync() } catch { /* ignore */ }
  /* ★0927 R16：退出时把持外部资源的服务一并收干净——原来只停 bot+落盘，
     MCP 子进程 / Chromium 实例 / 记忆桥会变孤儿（孤儿进程占端口、锁 sqlite、吃内存）。
     顺序：先断外部连接（bot 已停）→ 关浏览器 → 断 MCP → 停记忆桥 → 退出。 */
  /* ★1003 修复 4.79：收尾都是异步 fire-and-forget，原来固定 700ms 就 process.exit(0)——
     大概率把它们拦腰砍断，孤儿 MCP/Chromium 照样留下（R16 白干）。现在收集收尾 Promise，
     全部落地（或 5s 硬上限兜底，防个别 close 永挂卡住退出）再退出。 */
  const closers: Array<Promise<unknown>> = []
  try {
    const insts = browserEngine.allInstances()
    for (const inst of insts) closers.push(Promise.resolve(inst.close()).catch(() => { /* ignore */ }))
    console.log(`[pi-bridge] 退出清理：关闭 ${insts.length} 个浏览器实例`)
  } catch { /* ignore */ }
  try {
    for (const srv of getMcpStatus()) {
      if (srv?.name) closers.push(mcpHubDisconnect(String(srv.name), true).catch(() => { /* ignore */ }))   // keepConfig：关机不改配置
    }
  } catch { /* ignore */ }
  try { memoryBridge.stop() } catch { /* ignore */ }
  // 等收尾真正落地再退出；5s 硬上限兜底（绝不无限等）。落地后再留一点时间给下线通知
  const exitTimer = setTimeout(() => process.exit(0), 5000)
  void Promise.allSettled(closers).then(() => {
    clearTimeout(exitTimer)
    setTimeout(() => process.exit(0), 500)
  })
}
/* ★ 0924 诊断：抓「无痕猝死」。
 *   现象：后端起来 30 秒~几分钟后消失，日志戛然而止、.err 全空，
 *   而 gracefulExit / EADDRINUSE / orphan-guard **一条都没打**。
 *   被强杀（TerminateProcess）时这些钩子都不会触发；若是**事件循环空了**
 *   （所有 handle 都被 unref、或 server 被关掉），才会走 beforeExit —— 这两种是完全不同的病。
 *   定位到根因后可删。 */
process.on('beforeExit', (code) => {
  console.log(`[exit-trace] beforeExit code=${code} —— 事件循环已空（不是被强杀，是没有 handle 撑着进程了）`)
  try {
    console.log('[exit-trace] activeHandles=' + (process as any)._getActiveHandles?.().length
      + ' activeRequests=' + (process as any)._getActiveRequests?.().length)
  } catch { /* ignore */ }
})
process.on('exit', (code) => {
  console.log(`[exit-trace] exit code=${code} —— 进程正在退出（正常路径）`)
})
process.on('SIGINT', () => gracefulExit('SIGINT'))
process.on('SIGTERM', () => gracefulExit('SIGTERM'))
process.on('unhandledRejection', (reason) => { console.error('[unhandledRejection]', reason) })
process.on('uncaughtException', (err: any) => {
  console.error('[uncaughtException]', err)
  // 0913：端口被占必须退出——此前被吞掉后进程继续活着变僵尸：
  // 多个僵尸后端会重复连 QQ 网关（重复回复风险）、抢记忆库 DB（桥 exited code=1）、让"重启看起来没用"极难排查
  if (err?.code === 'EADDRINUSE') {
    console.error('[pi-bridge] 端口被占用（旧实例未清理？）→ 本进程退出')
    process.exit(1)
  }
})

// 启动记忆/知识库 Python 桥（后台，不阻塞；失败不影响主服务）
/** 记忆/知识库目录：**一律住在本应用自己的目录里**（用户 0919 口径）。
 *  打包版由壳注入 `NIS_MEMORY_DIR=%APPDATA%\nis\memory`；dev/命令行没壳注入 → `<数据根>/memory`。
 *  ⚠️ 以前这里写的是 `storagePath || defaultStorageRoot()`（= 设置→通用→存储目录）—— 于是：
 *     · 导入数据包时，包内 settings.json 把 storagePath 指到包里的 `niscs` → 应用直接读那个包的历史记忆
 *       （用户看到的"新装怎么还有历史记忆"就是这个）；
 *     · 换存储目录 → 记忆库跟着漂移。存储目录是给**对话工作区**用的、用户可换的位置，不该管记忆库。 */
const _injectedMemoryDir = String(process.env.NIS_MEMORY_DIR || '').trim()
process.env.NIS_MEMORY_DIR = _injectedMemoryDir || defaultMemoryDir()
/* 一次性搬家（只为**不丢老用户已有的记忆**）：目标目录还是空的、而"旧位置"（存储目录）里有库 → 拷过来。
 *   · 只拷不删，且只在目标为空时做 → 新装（旧位置也没库）什么都不做，记忆就是空的；
 *   · **只在"没壳注入"的场景做**（dev/命令行）。打包版按新口径"干净起步"：要历史就用「导入数据」，
 *     否则老安装那套（storagePath 被导入包指到 niscs）会把 1.63MB 历史又搬进新目录 —— 那正是要修的毛病。 */
function migrateLegacyMemoryDb(target: string): void {
  try {
    const has = (d: string, f: string) => !!d && fs.existsSync(path.join(d, f))
    if (has(target, 'memory_system.db') || has(target, 'knowledge.db')) return
    const legacy: string[] = [storageRootNow()]
    const docs = process.env.USERPROFILE ? path.join(process.env.USERPROFILE, 'Documents', 'NisData') : ''
    if (docs) legacy.push(docs)
    for (const src of legacy) {
      if (!src || path.resolve(src) === path.resolve(target)) continue
      const hits = ['memory_system.db', 'knowledge.db'].filter((f) => has(src, f))
      if (!hits.length) continue
      fs.mkdirSync(target, { recursive: true })
      for (const f of hits) fs.copyFileSync(path.join(src, f), path.join(target, f))
      console.log(`[memory-dir] 旧位置的记忆/知识库已搬入本应用目录：${src} → ${target}（只拷不删）`)
      return
    }
  } catch (e: any) {
    console.warn('[memory-dir] 旧库搬家跳过：', e?.message || e)
  }
}
  // 0924（库锁死安装目录）：禁用 storagePath 老库播种 —— 它会把「存储目录」下的废弃老库当种子灌进新家，
  // 0924 搬家时被它抢跑污染过一次；真库由 memoryBridge.seedFromLegacyMemoryDir 从 <DATA_ROOT>/memory 搬。
  // if (!_injectedMemoryDir) migrateLegacyMemoryDb(process.env.NIS_MEMORY_DIR)
// 0917：把「环境安装目录」透给记忆桥 —— 它会优先用这里的 memory-venv（设置→软件环境→记忆检索模型 装的）
process.env.NIS_ENV_DIR = envInstallDir()
/* ★ 0924：把自己标进环境变量 —— 让「由本后端拉起的子进程」能认出「我的宿主后端就是 8766 上的那一个」。
 *   AI 的 run_command 都是 execFile 且**不指定 env**（默认继承），
 *   所以从后端树里跑出来的脚本一定能读到它。用途见 _stop_backend.mjs / _restart_backend.mjs
 *   的「拒绝自杀」守卫：否则 AI 跑 `node _restart_backend.mjs` 会杀掉**正在承载这条命令的后端自身**
 *   —— 工具调用永远不返回、会话直接中断，而且不留任何退出痕迹（不是崩、不是优雅退出、不是端口占用），
 *   用户看到的就是「后端起来一会儿又断 + AI 突然不回话」。 */
process.env.NIS_BACKEND_PID = String(process.pid)
/* 打一行出来 —— 排查「后端为什么自己断了」时，先看这条就能确认「拒绝自杀」守卫是否已武装。 */
console.log(`[self-guard] NIS_BACKEND_PID=${process.pid} —— AI 若用 run_command 跑到 _stop/_restart_backend.mjs，会被它拒绝（防止把宿主后端杀掉）`)
memoryBridge.start()

/* ── 孤儿守卫（0919）────────────────────────────────────────────
 * 桌面壳把自己的 pid 通过 NIS_PARENT_PID 传进来。壳被**强杀**时（卸载器 `taskkill /F`、
 * 任务管理器结束进程、蓝屏前强退），本进程会变成孤儿并继续锁着 `pack\node.exe` / `pack\backend\`
 * → 卸载删不掉，最后剩一个残缺的 `pack\`（实测）。
 * 所以：父进程一旦不在，自己安静退出。只在壳拉起的场景生效（dev 手跑时没有这个变量，不受影响）。 */
const parentPid = Number(process.env.NIS_PARENT_PID || 0)
if (Number.isInteger(parentPid) && parentPid > 0) {
  const guard = setInterval(() => {
    try {
      process.kill(parentPid, 0) // 信号 0 = 只探测存在性，不发信号
    } catch {
      console.log(`[orphan-guard] 桌面壳（pid=${parentPid}）已退出 → 后端自行结束，放掉 pack 的句柄`)
      clearInterval(guard)
      process.exit(0)
    }
  }, 2000)
}
// 0913：冷启动（嵌入模型加载 + 磁盘缓存冷）实测可达 1-2 分钟 → 等待窗口 30s→90s，文案同步
void memoryBridge.waitReady(90000).then((ok) => {
  if (ok) {
    console.log('[memory-bridge] ready (memory_system.db + knowledge.db)')
  } else {
    // 0917：不再只留一句 "not ready" —— 说清楚为什么、怎么修，省得用户只能看到「导出失败」
    console.warn('[memory-bridge] not ready — 记忆/知识库功能不可用。'
      + '原因通常是本机没有可用的 Python；请到 设置→软件环境 安装「Python」与「记忆检索模型」后重启应用。')
  }
})

// ── 记忆维护定时器：启动后 5 分钟首跑，之后每 24h 一次 ──
// 清理软删/过期/旧事件 + Cold 层归档（遗忘机制）
async function runMemoryMaintenance(): Promise<void> {
  try {
    const r = await memoryBridge.call('memory_maintenance', {})
    console.log('[memory-maintenance]', JSON.stringify(r))
  } catch (e: any) {
    console.error('[memory-maintenance] failed:', e?.message || e)
  }
}
setTimeout(() => void runMemoryMaintenance(), 5 * 60 * 1000)
setInterval(() => void runMemoryMaintenance(), 24 * 60 * 60 * 1000)

// ── 文件历史 GC 定时器（0910 磁盘治理）：启动 2 分钟后首跑，之后每 24h（内部限流每小时最多一次）。
//    引用安全回收孤儿对象 + 超 500MB 预算时按最旧 tree 快照整链淘汰（tree 快照只写不读，零功能损失）。
//    workDirs=活跃会话工作区 + NIS 仓库根（cordis 会话可能拿仓库当工作区，在 NisData 之外）；
//    滞留处/孤儿工作区由 fileHistory 侧的 NisData 两层兜底扫描覆盖。──
/** 历史相关操作的工作区集合：活跃会话 + NIS 仓库根（cordis 会话可能拿仓库当工作区，在 NisData 之外） */
function historyWorkDirs(): string[] {
  const dirs = Array.from(sessions.values()).map(s => s.workDir?.trim()).filter(Boolean) as string[]
  /* ★开源整理批：原来写死 '<旧dev仓库>'（作者旧盘符）—— 别人机器上那是空路径。
     真实意图是"NiusDream 仓库根本身也可能被当工作区"，所以用 PROJECT_ROOT。 */
  dirs.push(PROJECT_ROOT)
  return dirs
}
async function runFileHistoryGc(): Promise<void> {
  /* ★1023z（实测"回复中途卡住 30s，工具/正文突然一次性全冒出来"）：**后台维护绝不能在会话运行期间跑**。
     真凭实据：`[file-history-gc] 孤儿 622 个，回收 17MB` 与 `session.approval/session.history 30s 超时`
     发生在同一秒 —— `enforceBudget` 是同步扫盘（622 个文件），把事件循环整段堵死，
     期间所有 RPC 超时、前端表现为"卡住然后一股脑刷出来"。而且启动后 2 分钟就跑，
     正好撞上刚重启就测试的时段（这次就是这么撞上的）。
     口径：会话在跑 → 推迟 5 分钟再来；跑完再记一条耗时（>200ms 就是会卡人的量级，必须暴露）。 */
  try {
    for (const s of sessions.values()) {
      if (s.status === 'running') {
        setTimeout(() => void runFileHistoryGc(), 5 * 60 * 1000)
        return
      }
    }
    const t0 = Date.now()
    const r = await enforceBudget(historyWorkDirs())
    const ms = Date.now() - t0
    if (r.deletedOrphans || r.freedBytes) console.log(`[file-history-gc] 孤儿 ${r.deletedOrphans} 个，回收 ${(r.freedBytes / 1048576).toFixed(0)}MB（耗时 ${ms}ms）`)
    if (ms > 200) console.warn(`[file-history-gc] ⚠ 本次耗时 ${ms}ms，这段时间事件循环被堵住（RPC 会超时）`)
  } catch (e: any) {
    console.error('[file-history-gc] failed:', e?.message || e)
  }
}
setTimeout(() => void runFileHistoryGc(), 2 * 60 * 1000)
setInterval(() => void runFileHistoryGc(), 24 * 60 * 60 * 1000)

/* ── 日志滚动清理（★1109）：`backend-restart-*.log` 每次重启产一个、**永不删**，
   实测 data/ 根下 **1131 个 / 57.9MB**，其中 **407 个超 30 天**（最早 9-9）。
   危害不是占磁盘（才 58MB），而是**排障时在一千个文件里翻**、以及每次 readdir 都更长。
   口径（与项目既有「宁留勿删」一致：**刚过期的只移走，不物理删**）：
     ① mtime 超过 LOG_KEEP_DAYS(30) 天的 `<data>/*.log` → **移到** `<data>/logs.trash/`（可手动移回）
     ② `logs.trash/` 里超过 LOG_TRASH_KEEP_DAYS(90) 天的 → 物理删（二次保留期兜底）
   ⚠️ 只处理 `DATA_ROOT` **根层**的 `.log`，**不动 `data/logs/`** —— 那是按会话分的执行日志（jsonl，归会话管）。 */
const LOG_KEEP_DAYS = 30
const LOG_TRASH_KEEP_DAYS = 90
async function runLogRotate(): Promise<void> {
  try {
    const now = Date.now()
    const day = 24 * 60 * 60 * 1000
    const trashDir = path.join(DATA_ROOT, 'logs.trash')
    let moved = 0, movedBytes = 0, purged = 0, purgedBytes = 0
    /* ① 移走超期日志（rename 同盘瞬时完成，不需要分片） */
    let names: string[] = []
    try { names = fs.readdirSync(DATA_ROOT).filter((f) => /\.log$/i.test(f)) } catch { /* 目录不可读：跳过本轮 */ }
    for (const f of names) {
      const src = path.join(DATA_ROOT, f)
      let st: fs.Stats
      try { st = fs.statSync(src) } catch { continue }
      if (!st.isFile()) continue
      if (now - st.mtimeMs <= LOG_KEEP_DAYS * day) continue
      try {
        fs.mkdirSync(trashDir, { recursive: true })
        fs.renameSync(src, path.join(trashDir, f))
        moved++; movedBytes += st.size
      } catch (e: any) {
        /* 失败**不静默**（可能是文件被占用）：留着原位，下轮再试 */
        console.warn('[log-rotate] 移走失败（保留原位）：', f, String(e?.message || e))
      }
    }
    /* ② trash 里超二次保留期的物理删 */
    try {
      for (const f of fs.readdirSync(trashDir)) {
        const p = path.join(trashDir, f)
        let st: fs.Stats
        try { st = fs.statSync(p) } catch { continue }
        if (!st.isFile()) continue
        if (now - st.mtimeMs <= LOG_TRASH_KEEP_DAYS * day) continue
        try { fs.rmSync(p, { force: true }); purged++; purgedBytes += st.size } catch { /* 下轮再试 */ }
      }
    } catch { /* trash 不存在：还没移过，正常 */ }
    if (moved || purged) {
      console.log(`[log-rotate] 移走 ${moved} 个日志到 logs.trash/（${(movedBytes / 1048576).toFixed(1)}MB），`
        + `清除 ${purged} 个超 ${LOG_TRASH_KEEP_DAYS} 天的（${(purgedBytes / 1048576).toFixed(1)}MB）`)
    }
  } catch (e: any) {
    console.error('[log-rotate] failed:', e?.message || e)
  }
}
setTimeout(() => void runLogRotate(), 4 * 60 * 1000)
setInterval(() => void runLogRotate(), 24 * 60 * 60 * 1000)

/* ── ★1109 运行状态采样器（**抓 CPU 90+ 的唯一可靠办法**）────────────────────────
   病：反馈「CPU 一直跑到 90+ 直到关闭网页版重新打开才好」。
   我查了四个角度（当前 CPU 0% / 昨天日志 eventloop≤1 / 无死循环 / 前端定时器都有清理），
   **没有后端证据** ⇒ 需要现场数据，不能靠猜。
   做法：每 10 秒往 `data/logs/telemetry.jsonl` 追加一行：
     时刻 / 后端 CPU% / 工作集MB / heapUsed / eventloop 最大延迟 / 在飞 RPC 数 / 连接数
   **只留最近 1 天**（每轮启动写一次新文件，超过 1 天的滚动删）——避免变成新的磁盘垃圾。
   ⚠️ 只观测，不改任何业务行为；采样本身用异步 fs.appendFile，不阻塞事件循环。 */
const TELEMETRY_FILE = path.join(DATA_ROOT, 'logs', 'telemetry.jsonl')
const TELEMETRY_KEEP_MS = 24 * 60 * 60 * 1000
const TELEMETRY_INTERVAL_MS = 10_000
let _telLastCpu = (() => { try { return process.cpuUsage() } catch { return { user: 0, system: 0 } } })()
let _telLastAt = Date.now()
function startTelemetry(): void {
  try {
    fs.mkdirSync(path.dirname(TELEMETRY_FILE), { recursive: true })
    /* 启动即滚动：超过 1 天的旧文件直接删（只留当前这一份） */
    try {
      const dir = path.dirname(TELEMETRY_FILE)
      for (const f of fs.readdirSync(dir)) {
        if (!/^telemetry.*\.jsonl$/.test(f)) continue
        const p = path.join(dir, f)
        try { if (Date.now() - fs.statSync(p).mtimeMs > TELEMETRY_KEEP_MS) fs.rmSync(p, { force: true }) } catch { }
      }
    } catch { }
    const timer = setInterval(() => {
      try {
        const now = Date.now()
        const cpu = process.cpuUsage(_telLastCpu)
        const elapsedMs = Math.max(1, now - _telLastAt)
        /* CPU% = 本周期用掉的 CPU 时间 / 墙上时间（单核 100% 基准；多核可 >100） */
        const cpuPct = Math.round(((cpu.user + cpu.system) / 1000) / elapsedMs * 1000) / 10
        _telLastCpu = process.cpuUsage()
        _telLastAt = now
        const mem = process.memoryUsage()
        const row = {
          t: now,
          cpuPct,
          rssMB: Math.round(mem.rss / 1048576),
          heapMB: Math.round(mem.heapUsed / 1048576),
          extMB: Math.round(mem.external / 1048576),
          eldMax: Math.round(eventLoopMaxMs()),
          rpc: rpcInflight.size,
          sessions: sessions.size,
          agents: agents.size,
        }
        /* 只在"有事发生"时写？不 —— 曲线要连续才看得出"从几点开始飙"。
           但 CPU 持续为 0 且无 RPC 时省一点：每 6 拍（1 分钟）必写一次，其余只在非零时写。 */
        const interesting = cpuPct > 5 || row.rpc > 0 || row.eldMax > 200
        const tick = Math.floor(now / TELEMETRY_INTERVAL_MS)
        if (interesting || tick % 6 === 0) fs.appendFile(TELEMETRY_FILE, JSON.stringify(row) + '\n', () => { })
      } catch { /* 采样失败绝不影响业务 */ }
    }, TELEMETRY_INTERVAL_MS)
    timer.unref()
  } catch (e: any) {
    console.error('[telemetry] 启动失败（不影响业务）：', e?.message || e)
  }
}
setTimeout(() => startTelemetry(), 15_000)   // 等 boot 忙完再开（避免把启动抖动记成"异常"）

// ── 文件历史自动清理定时器（0911 反馈）：启动 3 分钟后首跑，之后每 10 分钟巡检一次。
//    开关/阈值/比例来自设置页（historyAutoCleanEnabled / ThresholdMb / Pct；默认开 500MB/20%）。
//    未超阈值时只是一次轻量目录统计，不做任何删除；超阈值则裁掉最旧 pct% 记录并物理回收对象。──
/* ══ ★1116：内置浏览器 profile 缓存自动清理 ══
   实测（老板机器）：`data/browser-profile` 涨到 **8.0 GB / 168 个会话 profile**，其中 7.6 GB 是
   Chromium 的纯缓存（Cache 4.6GB + Code Cache 2.5GB + GPUCache/ShaderCache/…）。
   缓存随时可重建，但没人清就无限涨（每个会话一个 profile，跑一次浏览器留一份）。
   **只删 Chromium 自己标注为 cache 的目录** —— Cookies / Login Data / Local Storage / IndexedDB /
   Session Storage / Preferences / Extensions 一律不碰 ⇒ 不会掉任何账号登录。
   ⚠️ 别把 `blob_storage` / `Service Worker` / `IndexedDB` 加进来：少数站点把会话数据放那儿。 */
const BROWSER_CACHE_DIRS = new Set([
  'Cache', 'Code Cache', 'GPUCache', 'GPUPersistentCache', 'ShaderCache', 'GrShaderCache',
  'DawnGraphiteCache', 'DawnWebGPUCache', 'component_crx_cache', 'extensions_crx_cache',
  'Crashpad', 'BrowserMetrics', 'Safe Browsing', 'Safe Browsing Network',
  'segmentation_platform', 'OptimizationHints', 'AutofillStrikeDatabase', 'BudgetDatabase',
  'Site Characteristics Database', 'Feature Engagement Tracker', 'PersistentOriginTrials',
  'download_cache', 'Media Cache',
])
function dirSizeRecursive(p: string): number {
  let st: fs.Stats
  try { st = fs.lstatSync(p) } catch { return 0 }
  if (!st.isDirectory()) return st.size
  let names: string[] = []
  try { names = fs.readdirSync(p) } catch { return 0 }
  let total = 0
  for (const n of names) total += dirSizeRecursive(path.join(p, n))
  return total
}
/** 统计（clean=false）/ 统计并清理（clean=true）内置浏览器 profile 的缓存。同步执行，调用方负责节流。 */
function browserCacheSweep(clean: boolean): { totalBytes: number; cacheBytes: number; removed: number; freedBytes: number; skipped: number; profiles: number } {
  const root = path.join(DATA_ROOT, 'browser-profile')
  let totalBytes = 0, cacheBytes = 0, removed = 0, freedBytes = 0, skipped = 0, profiles = 0
  if (!fs.existsSync(root)) return { totalBytes, cacheBytes, removed, freedBytes, skipped, profiles }
  const walk = (d: string, depth: number) => {
    if (depth > 2) return
    let entries: fs.Dirent[] = []
    try { entries = fs.readdirSync(d, { withFileTypes: true }) } catch { return }
    for (const e of entries) {
      if (!e.isDirectory()) continue
      const full = path.join(d, e.name)
      if (BROWSER_CACHE_DIRS.has(e.name)) {
        const size = dirSizeRecursive(full)
        cacheBytes += size
        if (!clean) continue
        try {
          fs.rmSync(full, { recursive: true, force: true, maxRetries: 2, retryDelay: 150 })
          freedBytes += size; removed++
        } catch { skipped++ }   // 正被浏览器进程占用 → 跳过，绝不强删
      } else if (depth < 2) walk(full, depth + 1)
    }
  }
  for (const name of fs.readdirSync(root)) {
    const p = path.join(root, name)
    try { if (!fs.statSync(p).isDirectory()) continue } catch { continue }
    profiles++
    totalBytes += dirSizeRecursive(p)
    walk(p, 0)
  }
  return { totalBytes, cacheBytes, removed, freedBytes, skipped, profiles }
}
/** 定时巡检：总占用超阈值才清缓存（低于阈值连清理都不做，只是一次目录统计）。 */
function runBrowserCacheAutoClean(): void {
  try {
    const gs = globalSettings as any
    if (gs.browserCacheAutoCleanEnabled === false) return
    const tMb = Number(gs.browserCacheThresholdMb)
    if (!Number.isFinite(tMb) || tMb <= 0) return
    const before = browserCacheSweep(false)
    if (before.totalBytes < tMb * 1048576) return
    const r = browserCacheSweep(true)
    if (r.removed) {
      console.log(`[browser-autoclean] 清理 ${r.removed} 个缓存目录，释放 ${(r.freedBytes / 1048576).toFixed(0)}MB，` +
        `profile 占用 ${(before.totalBytes / 1048576).toFixed(0)}MB → ${((before.totalBytes - r.freedBytes) / 1048576).toFixed(0)}MB` +
        (r.skipped ? `（${r.skipped} 个被浏览器占用已跳过）` : ''))
    }
  } catch (e: any) {
    console.error('[browser-autoclean] failed:', e?.message || e)
  }
}
setTimeout(() => runBrowserCacheAutoClean(), 5 * 60 * 1000)   // 启动 5 分钟后首跑（避开 boot 高峰）
setInterval(() => runBrowserCacheAutoClean(), 60 * 60 * 1000).unref()

async function runHistoryAutoClean(): Promise<void> {
  try {
    const gs = globalSettings as any
    if (gs.historyAutoCleanEnabled === false) return
    const tMb = Number(gs.historyAutoCleanThresholdMb)
    if (!Number.isFinite(tMb) || tMb <= 0) return
    const pct = Number(gs.historyAutoCleanPct)
    const r = await autoCleanHistory(historyWorkDirs(), Math.floor(tMb * 1048576), Number.isFinite(pct) && pct > 0 ? pct : 20)
    if (r.triggered) console.log(`[file-history-autoclean] 清理最旧 ${r.removedChanges} 条记录（${r.removedWorkspaces} 个工作区），释放 ${(r.freedBytes / 1048576).toFixed(1)}MB，当前占用 ${(r.totalBytes / 1048576).toFixed(0)}MB`)
  } catch (e: any) {
    console.error('[file-history-autoclean] failed:', e?.message || e)
  }
}
setTimeout(() => void runHistoryAutoClean(), 3 * 60 * 1000)
setInterval(() => void runHistoryAutoClean(), 10 * 60 * 1000)
